window.CC_CASES=[{"id": "faretta", "name": "Faretta v. California", "cite": "422 U.S. 806 (1975)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/109309/faretta-v-california/", "verify": false, "charge": "Grand theft (California state court, Los Angeles)", "setup": "Faretta was charged with grand theft in Los Angeles. Weeks before trial he asked to represent himself, saying the public defender's office was too overloaded to give him real attention. The judge first allowed it, then questioned him about the hearsay rule and the law on picking a jury, decided he had no constitutional right to defend himself, and forced the public defender back on him. You're Faretta, back in front of that judge.", "role": "You are the defendant asking to represent yourself.", "cards": [{"id": "faretta1", "case": "state", "stage": "Faretta request (before trial)", "who": "judge", "say": "In the Faretta matter, I brought you back down here to do some reconsideration as to whether or not you should continue to represent yourself.", "say_real": true, "say_src": "Faretta v. California, 422 U.S. 806, 808 n.3 (1975) (trial judge, quoted colloquy)", "need": [{"k": "a clear request to represent yourself", "any": ["represent(ing)? myself", "self[- ]representation", "pro per", "pro se"]}, {"k": "\"knowingly and voluntarily\"", "any": ["knowing(ly)?", "voluntar(y|ily)", "intelligent"]}, {"k": "timely (well before trial)", "any": ["before trial", "timely", "weeks before"]}], "avoid": [{"any": ["\\bmaybe\\b", "\\bI guess\\b", "\\bunless\\b", "\\bonly if\\b"], "why": "A conditional or unsure request can be denied as not unequivocal."}], "win": "REQUEST HEARD", "lose": "REQUEST DENIED (equivocal)", "model": "Your Honor, I still unequivocally ask to represent myself. I'm making this choice knowingly and voluntarily, weeks before trial. The public defender's office has a heavy caseload, and I want to control my own defense.", "why": "Faretta's request was clear, made well before trial, and he gave a reason. Unequivocal + timely + knowing is the formula every court still uses.", "cite": "Faretta v. California, 422 U.S. 806 (1975)", "choices": [{"text": "I unequivocally ask to represent myself, knowingly and voluntarily, and weeks before trial.", "ok": 1, "src": "model answer", "why": "Wins: says a clear request to represent yourself, \"knowingly and voluntarily\", timely (well before trial)."}, {"text": "I guess I'd go it alone, unless you can get me a lawyer who isn't so busy.", "ok": 0, "src": "common mistake", "why": "A conditional or unsure request can be denied as not unequivocal."}, {"text": "Because I'm smarter than the public defender.", "ok": 0, "src": "common mistake", "why": "Insulting counsel isn't a reason the court can grant. It just makes you look like you'll be disruptive."}], "trap": {"2": "Insulting counsel isn't a reason the court can grant. It just makes you look like you'll be disruptive."}}, {"id": "faretta2", "case": "state", "stage": "Faretta request (before trial)", "who": "judge", "say": "How many exceptions are there to the hearsay rule?", "say_real": true, "say_src": "Faretta, 422 U.S. at 809 n.3 (trial judge, quoted colloquy)", "need": [{"k": "legal knowledge isn't the test", "any": ["technical (legal )?knowledge", "not the test", "isn'?t the test", "not relevant"]}, {"k": "\"knowing and intelligent\" waiver", "any": ["knowing", "intelligent"]}, {"k": "Sixth Amendment / constitutional right", "any": ["sixth amendment", "constitutional right"]}], "avoid": [{"any": ["give me (some )?time", "I'?ll learn (it )?later"], "why": "Asking for time to study turns the request into a delay request."}], "win": "OBJECTION NOTED: WRONG TEST", "lose": "REQUEST DENIED", "model": "Your Honor, respectfully, my technical legal knowledge is not the test. The question is whether my waiver of counsel is knowing and intelligent, and it is. I have a Sixth Amendment right to represent myself, and I will follow the rules of evidence and procedure.", "why": "This is exactly what Faretta's judge did wrong. The Supreme Court said his technical legal knowledge had nothing to do with whether he knowingly chose to defend himself.", "cite": "Faretta, 422 U.S. at 835-836", "choices": [{"text": "My technical legal knowledge isn't the test. My waiver is knowing and intelligent, and I have a Sixth Amendment right to represent myself.", "ok": 1, "src": "model answer", "why": "Wins: says legal knowledge isn't the test, \"knowing and intelligent\" waiver, Sixth Amendment / constitutional right."}, {"text": "Well, the hearsay rule would, I guess, be called the best evidence rule, your Honor. And there are several exceptions in case law...", "ok": 0, "src": "real: Faretta's answer, 422 U.S. at 809 n.3", "why": "Faretta guessed and got it wrong, and the judge used that to revoke pro per. The Supreme Court later said the quiz was the wrong test, but don't take the bait: name the real test instead."}, {"text": "Hearsay is when somebody lies about you.", "ok": 0, "src": "common mistake", "why": "Loses: a wrong legal answer, and it never names the real test (knowing and intelligent waiver, Sixth Amendment)."}, {"text": "Then give me some time to study and ask me again.", "ok": 0, "src": "common mistake", "why": "Asking for time to study turns the request into a delay request."}]}, {"id": "faretta3", "case": "state", "stage": "Faretta request (before trial)", "who": "da", "say": "The People object. He'll make a mess of this trial. The Court should keep counsel on him for his own good.", "say_real": false, "need": [{"k": "\"the choice is mine\"", "any": ["choice is mine", "my (own )?choice", "my (own )?decision"]}, {"k": "\"dangers and disadvantages\"", "any": ["danger", "disadvantage", "risk"]}, {"k": "Sixth Amendment", "any": ["sixth amendment", "constitution"]}], "avoid": [{"any": ["\\bliar\\b", "unfair", "just wants to win"], "why": "Attacking the prosecutor doesn't answer the objection and looks disruptive."}], "win": "OBJECTION OVERRULED", "lose": "OBJECTION SUSTAINED", "model": "Your Honor, I understand the dangers and disadvantages of representing myself. Under the Sixth Amendment the choice is mine, even if it turns out to hurt my own case. I won't disrupt the trial, and I'll accept standby counsel if the Court appoints one.", "why": "Faretta says a defendant's informed choice must be honored even if it's to his own detriment. 'For his own good' is not a legal reason to force a lawyer on him.", "cite": "Faretta, 422 U.S. at 834 & n.46", "choices": [{"text": "I understand the dangers and disadvantages. Under the Sixth Amendment the choice is mine, and I won't disrupt the trial.", "ok": 1, "src": "model answer", "why": "Wins: says \"the choice is mine\", \"dangers and disadvantages\", Sixth Amendment."}, {"text": "You're right, I'll keep the public defender.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"the choice is mine\"; \"dangers and disadvantages\"; Sixth Amendment."}, {"text": "The DA just wants to win. This is unfair.", "ok": 0, "src": "common mistake", "why": "Attacking the prosecutor doesn't answer the objection and looks disruptive."}]}, {"id": "faretta5", "case": "state", "stage": "Faretta request (before trial)", "who": "judge", "say": "We are going to treat you like a gentleman. We are going to respect you. We are going to give you every chance, but you are going to play with the same ground rules that anybody plays.", "say_real": true, "say_src": "Faretta, 422 U.S. at 808 n.2 (trial judge, quoted)", "need": [{"k": "\"I understand\"", "any": ["understand"]}, {"k": "same rules as any lawyer", "any": ["same (ground )?rules", "rules of evidence", "evidence code"]}, {"k": "\"I still choose\"", "any": ["\\bstill\\b"]}], "avoid": [{"any": ["cut me (some )?slack", "I don'?t know (the|those) (ground )?rules"], "why": "Asking for slack or admitting you don't know the rules hands the judge a reason to deny."}], "win": "REQUEST STANDS", "lose": "PRO PER REVOKED", "model": "I understand, Your Honor. I'll be held to the same ground rules as any lawyer, including the Evidence Code, and I expect no special treatment. Knowing that, I still choose to represent myself.", "why": "Repeat the warning back in your own words and reaffirm. That is the record a reviewing court looks for.", "cite": "Faretta, 422 U.S. at 834-835", "choices": [{"text": "I understand, Your Honor. I'll play by the same ground rules as any lawyer, and I still choose to represent myself.", "ok": 1, "src": "model answer", "why": "Acknowledges the warning and reaffirms the choice on the record."}, {"text": "I'm sure you'll cut me some slack, I'm not a lawyer.", "ok": 0, "src": "common mistake", "why": "Asking for slack hands the judge a reason to deny."}, {"text": "Okay.", "ok": 0, "src": "common mistake", "why": "Too thin: the record never shows you understood the rules and still chose to go pro per."}]}, {"id": "faretta4", "case": "state", "stage": "Quiz", "who": "quiz", "say": "What did the Supreme Court decide in Faretta?", "say_real": false, "need": [{"k": "a right to represent yourself", "any": ["represent (him|her|them)?sel(f|ves)", "represent yourself", "self[- ]representation"]}, {"k": "knowing and intelligent waiver", "any": ["knowing", "intelligent"]}], "avoid": [{"any": ["legal[- ]knowledge test", "pass(es)? a test"], "why": "Faretta rejected a legal-knowledge test."}], "win": "CORRECT", "lose": "WRONG", "model": "The Sixth Amendment gives a defendant the right to self-representation, as long as he gives up counsel knowingly and intelligently after being warned of the dangers.", "why": "This is the root case for every pro per request, state or federal.", "cite": "Faretta v. California, 422 U.S. 806 (1975)", "choices": [{"text": "A Sixth Amendment right to self-representation, if the waiver of counsel is knowing and intelligent.", "ok": 1, "src": "model answer", "why": "Wins: says a right to represent yourself, knowing and intelligent waiver."}, {"text": "Only a right to a free lawyer.", "ok": 0, "src": "common mistake", "why": "Loses: never says a right to represent yourself; knowing and intelligent waiver."}, {"text": "A right to represent yourself only if you pass a legal-knowledge test.", "ok": 0, "src": "common mistake", "why": "Faretta rejected a legal-knowledge test."}]}], "real": "The Supreme Court (6-3) held that the Sixth Amendment gives a defendant the right to conduct his own defense when he knowingly and intelligently gives up counsel. Forcing a lawyer on Faretta was error, so the judgment was vacated and the case sent back.", "cast": "state"}, {"id": "andersen", "name": "Arthur Andersen LLP v. United States", "cite": "544 U.S. 696 (2005)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/142899/arthur-andersen-llp-v-united-states/", "verify": false, "charge": "Witness tampering, 18 U.S.C. \u00a7 1512(b)(2)(A)-(B): \"knowingly ... corruptly persuading\" others to withhold or destroy documents", "setup": "As the Enron scandal broke in 2001 and an SEC inquiry looked likely, managers at the accounting firm Arthur Andersen kept reminding staff to follow the firm's document-retention policy, and huge amounts of paper and email were destroyed. The firm was indicted in Texas under \u00a7 1512(b). You speak for the defense at the jury-instruction conference and after.", "role": "You are the defense (the firm is the defendant).", "cards": [{"id": "andersen1", "case": "fed", "stage": "Jury-instruction conference", "who": "judge", "say": "Proposed instruction: \"even if [the defendant] honestly and sincerely believed that its conduct was lawful, you may find [the defendant] guilty.\" Any objection?", "say_real": true, "say_src": "Arthur Andersen, 544 U.S. at 706 (instruction text verbatim; the framing words Proposed instruction / Any objection? are added)", "need": [{"k": "\"I object\"", "any": ["\\bobject"]}, {"k": "\"consciousness of wrongdoing\"", "any": ["consciousness of wrongdoing", "wrongdoing"]}, {"k": "\"knowingly ... corruptly\"", "any": ["corrupt"]}], "avoid": [{"any": ["no objection"], "why": "If you don't object, the bad instruction goes to the jury and the issue is hard to win on appeal."}], "win": "OBJECTION PRESERVED", "lose": "INSTRUCTION GIVEN", "model": "Yes, Your Honor, I object. Section 1512(b) requires that the defendant knowingly and corruptly persuaded someone, and that means consciousness of wrongdoing. An instruction that lets the jury convict even if the defendant honestly believed its conduct was lawful drops that element.", "why": "The Supreme Court held this exact kind of instruction was wrong: \"knowingly ... corruptly\" reaches only people conscious of wrongdoing.", "cite": "Arthur Andersen, 544 U.S. at 705-706", "choices": [{"text": "I object. \"Knowingly ... corruptly\" requires consciousness of wrongdoing, and this instruction drops it.", "ok": 1, "src": "model answer", "why": "Wins: says \"I object\", \"consciousness of wrongdoing\", \"knowingly ... corruptly\"."}, {"text": "No objection, Your Honor.", "ok": 0, "src": "common mistake", "why": "If you don't object, the bad instruction goes to the jury and the issue is hard to win on appeal."}, {"text": "We just followed our document policy, so we're not guilty.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"I object\"; \"consciousness of wrongdoing\"; \"knowingly ... corruptly\"."}]}, {"id": "andersen2", "case": "fed", "stage": "Jury-instruction conference", "who": "ausa", "say": "The jury doesn't need to find the defendant had any particular proceeding in mind. Destroying documents before an investigation is enough.", "say_real": false, "need": [{"k": "\"nexus\" to a particular proceeding", "any": ["nexus", "particular (official )?proceeding", "specific (official )?proceeding"]}, {"k": "the proceeding must be foreseen / contemplated", "any": ["contemplat", "foresee", "in mind"]}], "avoid": [{"any": ["\\bI agree\\b", "\\bwe agree\\b"], "why": "Agreeing gives up the nexus element."}], "win": "OBJECTION PRESERVED", "lose": "INSTRUCTION GIVEN", "model": "Your Honor, the instruction must require a nexus to a particular official proceeding. The proceeding doesn't have to be pending yet, but the defendant has to have it in contemplation. You can't knowingly and corruptly persuade someone to withhold things from a proceeding you don't foresee.", "why": "Andersen applied the nexus idea from Aguilar to \u00a7 1512(b). The statute says the proceeding need not be pending, but it still has to be one the defendant foresaw.", "cite": "Arthur Andersen, 544 U.S. at 707-708; 18 U.S.C. \u00a7 1512(f)(1)", "choices": [{"text": "The jury must find a nexus to a particular official proceeding the defendant had in contemplation, even if not yet pending.", "ok": 1, "src": "model answer", "why": "Wins: says \"nexus\" to a particular proceeding, the proceeding must be foreseen / contemplated."}, {"text": "I agree it's a close call, Your Honor.", "ok": 0, "src": "common mistake", "why": "Agreeing gives up the nexus element."}, {"text": "Lots of companies have document policies.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"nexus\" to a particular proceeding; the proceeding must be foreseen / contemplated."}]}, {"id": "andersen3", "case": "fed", "stage": "Any hearing", "who": "ausa", "say": "Your Honor, the defendant asked someone not to talk. That's persuasion, and persuasion is all \u00a7 1512(b) needs.", "say_real": false, "need": [{"k": "persuasion isn't automatically a crime", "any": ["not (inherently|automatically|always)", "isn'?t (inherently|automatically|always)", "innocent", "not (all|every)"]}, {"k": "\"corruptly\"", "any": ["corrupt"]}, {"k": "the government must prove it", "any": ["must prove", "has to (prove|show)", "burden"]}], "avoid": [{"any": ["\\bI (never|didn'?t)\\b", "\\bshe\\b", "\\bher\\b"], "why": "Never argue the facts or talk about the witness. Argue the element."}], "win": "ARGUMENT NOTED", "lose": "COURT ADOPTS THE GOVERNMENT'S VIEW", "model": "Your Honor, under Arthur Andersen persuasion is not inherently wrongful. A parent asking a child to use a privilege, or a lawyer advising a client, isn't a crime. The government has to prove the persuasion was done knowingly and corruptly, with consciousness of wrongdoing.", "why": "The Court gave everyday examples of lawful persuasion to show why the word \"corruptly\" does the real work in \u00a7 1512(b).", "cite": "Arthur Andersen, 544 U.S. at 703-704", "choices": [{"text": "Persuasion is not inherently wrongful. The government must prove I acted knowingly and corruptly, with consciousness of wrongdoing.", "ok": 1, "src": "model answer", "why": "Wins: says persuasion isn't automatically a crime, \"corruptly\", the government must prove it."}, {"text": "I never asked anyone not to talk.", "ok": 0, "src": "common mistake", "why": "Denying the facts at a hearing hands the government a statement. Stick to what they must prove."}, {"text": "Persuasion is free speech, so it's fine.", "ok": 0, "src": "common mistake", "why": "Loses: never says persuasion isn't automatically a crime; \"corruptly\"; the government must prove it."}], "trap": {"1": "Denying the facts at a hearing hands the government a statement. Stick to what they must prove."}}, {"id": "andersen4", "case": "fed", "stage": "Quiz", "who": "quiz", "say": "Which words in \u00a7 1512(b) did Arthur Andersen say limit the statute, and what do they require?", "say_real": false, "need": [{"k": "\"knowingly\"", "any": ["knowing"]}, {"k": "\"corruptly persuades\"", "any": ["corrupt"]}, {"k": "consciousness of wrongdoing", "any": ["wrongdoing"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "\"Knowingly ... corruptly persuades.\" Together they require consciousness of wrongdoing.", "why": "These are the words the government has to prove in your \u00a7 1512(b) complaint.", "cite": "Arthur Andersen, 544 U.S. at 705-706", "choices": [{"text": "\"Knowingly ... corruptly persuades\": consciousness of wrongdoing.", "ok": 1, "src": "model answer", "why": "Wins: says \"knowingly\", \"corruptly persuades\", consciousness of wrongdoing."}, {"text": "\"Intimidates\": any pressure on a witness is a crime.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"knowingly\"; \"corruptly persuades\"; consciousness of wrongdoing."}, {"text": "\"Official proceeding\": any investigation counts.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"knowingly\"; \"corruptly persuades\"; consciousness of wrongdoing."}]}], "real": "The Supreme Court unanimously reversed the appeals court's judgment upholding the conviction and sent the case back. The jury instructions failed to convey that \"knowingly ... corruptly persuades\" requires consciousness of wrongdoing, and they didn't require any nexus between the persuasion and a particular official proceeding.", "cast": "fed"}, {"id": "aguilar", "name": "United States v. Aguilar", "cite": "515 U.S. 593 (1995)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/117962/united-states-v-aguilar/", "verify": false, "charge": "Obstruction of justice, 18 U.S.C. \u00a7 1503 (omnibus clause), and disclosing a wiretap, 18 U.S.C. \u00a7 2232(c)", "setup": "A federal district judge in California learned of a wiretap and told someone about it. Later, while a grand jury was investigating, FBI agents interviewed him and he gave them false answers. The government charged him under \u00a7 1503 on the theory that lying to the agents obstructed the grand jury. You're the defendant challenging that theory.", "role": "You are the defendant.", "cards": [{"id": "aguilar1", "case": "fed", "stage": "Motion for acquittal", "who": "judge", "say": "The government says lying to an FBI agent during a grand jury investigation obstructs the grand jury. Why isn't that enough?", "say_real": false, "need": [{"k": "\"nexus\"", "any": ["nexus"]}, {"k": "relationship in time, causation or logic", "any": ["causation", "natural and probable"]}, {"k": "the agent might never testify", "any": ["(might|may) (not|never) testify", "not subpoenaed", "never subpoenaed"]}], "avoid": [{"any": ["\\bI didn'?t lie\\b", "\\bI never lied\\b"], "why": "Argue the element, not your own version of the facts."}], "win": "MOTION GRANTED", "lose": "MOTION DENIED", "model": "Your Honor, the statute requires a nexus: the act must have a relationship in time, causation, or logic with the judicial proceeding, so that its natural and probable effect is to interfere with it. The agent was never subpoenaed and may never testify before the grand jury. A false statement to an investigator who might or might not testify is not enough.", "why": "This is the Aguilar holding in plain words. An investigation is not the same thing as a proceeding.", "cite": "United States v. Aguilar, 515 U.S. 593, 599-601 (1995)", "choices": [{"text": "There's no nexus: no relationship in time, causation, or logic with the grand jury. The agent was never subpoenaed and may never testify.", "ok": 1, "src": "model answer", "why": "Wins: says \"nexus\", relationship in time, causation or logic, the agent might never testify."}, {"text": "I didn't lie to anybody.", "ok": 0, "src": "common mistake", "why": "Argue the element, not your own version of the facts."}, {"text": "The FBI isn't a court, so it doesn't count.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"nexus\"; relationship in time, causation or logic; the agent might never testify."}]}, {"id": "aguilar2", "case": "fed", "stage": "Motion for acquittal", "who": "ausa", "say": "The defendant knew a grand jury was investigating. That's nexus.", "say_real": false, "need": [{"k": "knowing about an investigation isn't enough", "any": ["not enough", "isn'?t enough"]}, {"k": "must know the act is likely to affect the proceeding", "any": ["likely to affect", "natural and probable"]}, {"k": "\"nexus\"", "any": ["nexus"]}], "avoid": [], "win": "OBJECTION OVERRULED", "lose": "OBJECTION SUSTAINED", "model": "Knowing there's an investigation is not enough, Your Honor. The nexus requirement means the government must show I knew my act was likely to affect the proceeding itself. Without that, there's no intent to obstruct it.", "why": "Aguilar says a defendant who doesn't know his act is likely to affect the proceeding lacks the required intent.", "cite": "Aguilar, 515 U.S. at 599", "choices": [{"text": "Knowing about an investigation isn't enough. Nexus means I knew my act was likely to affect the proceeding itself.", "ok": 1, "src": "model answer", "why": "Wins: says knowing about an investigation isn't enough, must know the act is likely to affect the proceeding, \"nexus\"."}, {"text": "Fine, but I was just nervous.", "ok": 0, "src": "common mistake", "why": "Loses: never says knowing about an investigation isn't enough; must know the act is likely to affect the proceeding; \"nexus\"."}, {"text": "There was no grand jury.", "ok": 0, "src": "common mistake", "why": "Loses: never says knowing about an investigation isn't enough; must know the act is likely to affect the proceeding; \"nexus\"."}]}, {"id": "aguilar4", "case": "fed", "stage": "Quiz", "who": "quiz", "say": "Aguilar is a \u00a7 1503 case. Why does it matter in a \u00a7 1512(b) case?", "say_real": false, "need": [{"k": "Arthur Andersen carried it over", "any": ["andersen"]}, {"k": "\"nexus\"", "any": ["nexus"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "Because Arthur Andersen applied Aguilar's nexus requirement to \u00a7 1512(b): the persuasion must be tied to a particular official proceeding the defendant had in mind.", "why": "Cite both together: Aguilar for what nexus means, Andersen for why it applies to \u00a7 1512(b).", "cite": "Arthur Andersen, 544 U.S. at 707-708", "choices": [{"text": "Arthur Andersen applied Aguilar's nexus requirement to \u00a7 1512(b).", "ok": 1, "src": "model answer", "why": "Wins: says Arthur Andersen carried it over, \"nexus\"."}, {"text": "It doesn't. \u00a7 1503 is a different statute, so nexus never applies.", "ok": 0, "src": "common mistake", "why": "Loses: never says Arthur Andersen carried it over."}, {"text": "Because Aguilar was also a witness tampering case.", "ok": 0, "src": "common mistake", "why": "Loses: never says Arthur Andersen carried it over; \"nexus\"."}]}], "real": "The Supreme Court held that \u00a7 1503 requires a nexus: the act must have a relationship in time, causation, or logic with the judicial proceeding. False statements to agents who might or might not testify before the grand jury were not enough, so the \u00a7 1503 conviction stayed reversed. On the separate wiretap-disclosure count, though, the Court ruled for the government.", "cast": "c3"}, {"id": "fowler", "name": "Fowler v. United States", "cite": "563 U.S. 668 (2011)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/217514/fowler-v-united-states/", "verify": false, "charge": "Killing a person to prevent communication to a federal law enforcement officer, 18 U.S.C. \u00a7 1512(a)(1)(C)", "setup": "A man and others were getting ready to rob a bank in Florida when a local police officer came upon them, and the man shot and killed the officer. Federal prosecutors charged him under \u00a7 1512(a)(1)(C), which covers killing someone to stop them from telling a federal officer about a federal crime. The officer was local, and there was little to show anything would have reached a federal officer. You're the defendant arguing the federal element.", "role": "You are the defendant (federal element only).", "cards": [{"id": "fowler1", "case": "fed", "stage": "Jury instructions", "who": "judge", "say": "The government says it only has to show it was possible the information could reach a federal officer. Your response?", "say_real": false, "need": [{"k": "\"reasonable likelihood\"", "any": ["reasonable likelihood"]}, {"k": "a federal officer", "any": ["federal (law enforcement )?(officer|agent)"]}, {"k": "a bare possibility isn't enough", "any": ["remote", "hypothetical", "not enough", "isn'?t enough"]}], "avoid": [], "win": "INSTRUCTION MODIFIED", "lose": "INSTRUCTION GIVEN", "model": "Your Honor, a mere possibility isn't enough. The government must show a reasonable likelihood that, if the person had communicated with law enforcement, at least one relevant communication would have been made to a federal officer. That likelihood has to be more than remote or purely hypothetical.", "why": "That's the Fowler test. 'Possible' is a much easier standard than 'reasonably likely', so make the court say the right one.", "cite": "Fowler v. United States, 563 U.S. 668, 677-678 (2011)", "choices": [{"text": "A possibility isn't enough. They must show a reasonable likelihood a communication would have gone to a federal officer.", "ok": 1, "src": "model answer", "why": "Wins: says \"reasonable likelihood\", a federal officer, a bare possibility isn't enough."}, {"text": "That sounds fine to me.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"reasonable likelihood\"; a federal officer; a bare possibility isn't enough."}, {"text": "They have to prove I knew an FBI agent by name.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"reasonable likelihood\"; a federal officer; a bare possibility isn't enough."}]}, {"id": "fowler2", "case": "fed", "stage": "Jury instructions", "who": "ausa", "say": "The government doesn't have to prove the defendant had any particular federal officer in mind.", "say_real": false, "need": [{"k": "concede the true part", "any": ["\\bcorrect\\b", "\\btrue\\b", "\\bagree\\b", "not required"]}, {"k": "\"but\" a reasonable likelihood still required", "any": ["reasonable likelihood"]}, {"k": "federal officer", "any": ["federal"]}], "avoid": [], "win": "ARGUMENT NOTED", "lose": "COURT ADOPTS THE GOVERNMENT'S VIEW", "model": "That's correct, Your Honor: no particular federal officer has to be in mind. But the government still has to show a reasonable likelihood that a relevant communication would have been made to a federal officer. A purely local matter doesn't meet that.", "why": "Conceding the true part makes you credible. Then pivot right back to the element they still owe.", "cite": "Fowler, 563 U.S. at 673-674, 677-678", "choices": [{"text": "Correct, no particular officer. But they still need a reasonable likelihood of a communication to a federal officer.", "ok": 1, "src": "model answer", "why": "Wins: says concede the true part, \"but\" a reasonable likelihood still required, federal officer."}, {"text": "Then I have no argument.", "ok": 0, "src": "common mistake", "why": "Loses: never says concede the true part; \"but\" a reasonable likelihood still required; federal officer."}, {"text": "They have to prove I named a specific FBI agent.", "ok": 0, "src": "common mistake", "why": "Loses: never says concede the true part; \"but\" a reasonable likelihood still required; federal officer."}]}, {"id": "fowler3", "case": "fed", "stage": "Close of the government's case", "who": "judge", "say": "The government rests. Anything from the defense?", "say_real": false, "need": [{"k": "Rule 29 / judgment of acquittal", "any": ["acquittal", "rule 29"]}, {"k": "insufficient evidence", "any": ["insufficient", "no evidence"]}, {"k": "the federal element", "any": ["federal"]}], "avoid": [{"any": ["\\bI'?m innocent\\b"], "why": "Argue the evidence, not your own denial."}], "win": "MOTION PRESERVED", "lose": "WAIVED", "model": "Yes, Your Honor. Under Rule 29 I move for a judgment of acquittal. There's no evidence of a reasonable likelihood that any communication would have reached a federal officer, so the evidence is insufficient on that element.", "why": "A Rule 29 motion at the close of the government's case preserves a sufficiency challenge. Name the missing element.", "cite": "Fed. R. Crim. P. 29(a)", "choices": [{"text": "Under Rule 29 I move for acquittal. There's no evidence a communication would have reached a federal officer, so the evidence is insufficient.", "ok": 1, "src": "model answer", "why": "Wins: says Rule 29 / judgment of acquittal, insufficient evidence, the federal element."}, {"text": "No, Your Honor.", "ok": 0, "src": "common mistake", "why": "Loses: never says Rule 29 / judgment of acquittal; insufficient evidence; the federal element."}, {"text": "I'm innocent and the jury should know it.", "ok": 0, "src": "common mistake", "why": "Argue the evidence, not your own denial."}]}], "real": "The Supreme Court vacated the Eleventh Circuit's judgment upholding the \u00a7 1512(a)(1)(C) conviction and sent the case back. It held the government must show a reasonable likelihood that, had the victim communicated with law enforcement, at least one relevant communication would have been made to a federal officer; a remote, outlandish or simply hypothetical possibility isn't enough.", "cast": "fed"}, {"id": "fischer", "name": "Fischer v. United States", "cite": "603 U.S. 480 (2024)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/9986255/fischer-v-united-states/", "verify": false, "charge": "Obstructing an official proceeding, 18 U.S.C. \u00a7 1512(c)(2) (plus other January 6 charges)", "setup": "A former police officer took part in the January 6, 2021 breach of the Capitol and was charged with several crimes, including \u00a7 1512(c)(2), which punishes anyone who \"otherwise\" obstructs an official proceeding. The trial judge dismissed that count; the D.C. Circuit reinstated it. You're the defendant arguing how far \"otherwise\" reaches.", "role": "You are the defendant arguing a motion to dismiss one count.", "cards": [{"id": "fischer1", "case": "fed", "stage": "Motion to dismiss", "who": "judge", "say": "The government says \u00a7 1512(c)(2) covers any obstruction of an official proceeding at all. Why read it narrowly?", "say_real": false, "need": [{"k": "read (c)(2) with (c)(1)", "any": ["\\(c\\)\\(1\\)"]}, {"k": "records / documents / evidence", "any": ["records", "documents", "evidence", "integrity", "availability"]}, {"k": "\"dismiss\"", "any": ["dismiss"]}], "avoid": [{"any": ["\\bpolitical\\b", "\\bwitch hunt\\b"], "why": "Politics isn't a legal argument. Argue the text."}], "win": "COUNT DISMISSED", "lose": "MOTION DENIED", "model": "Your Honor, subsection (c)(2) has to be read with (c)(1), which is about records, documents, and other objects. The word \"otherwise\" limits (c)(2) to impairing the availability or integrity of evidence used in a proceeding, or trying to. This count doesn't allege that, so I move to dismiss it.", "why": "The Supreme Court read (c)(2) in light of (c)(1): it's about evidence used in the proceeding, not every kind of obstruction.", "cite": "Fischer v. United States, 603 U.S. 480 (2024)", "choices": [{"text": "Read (c)(2) with (c)(1): it's limited to impairing records, documents or other evidence. This count doesn't allege that, so dismiss it.", "ok": 1, "src": "model answer", "why": "Wins: says read (c)(2) with (c)(1), records / documents / evidence, \"dismiss\"."}, {"text": "This whole case is a political witch hunt.", "ok": 0, "src": "common mistake", "why": "Politics isn't a legal argument. Argue the text."}, {"text": "The government is being too broad.", "ok": 0, "src": "common mistake", "why": "Loses: never says read (c)(2) with (c)(1); records / documents / evidence; \"dismiss\"."}]}, {"id": "fischer2", "case": "fed", "stage": "Motion to dismiss", "who": "ausa", "say": "\"Otherwise\" means \"in any other way.\" Congress wrote a catch-all.", "say_real": false, "need": [{"k": "a catch-all would make the rest of \u00a7 1512 pointless", "any": ["superfluous", "swallow", "pointless", "unnecessary"]}, {"k": "tied to evidence", "any": ["records", "documents", "evidence"]}], "avoid": [], "win": "ARGUMENT ACCEPTED", "lose": "ARGUMENT REJECTED", "model": "If \"otherwise\" meant any obstruction at all, the specific crimes Congress listed elsewhere in \u00a7 1512 would be unnecessary, and a 20-year felony would reach ordinary advocacy and lobbying. The clause is tied to (c)(1): impairing records, documents, or other things used in the proceeding.", "why": "The Court rejected the catch-all reading partly because it would make the narrower provisions pointless and sweep in a huge range of conduct.", "cite": "Fischer, 603 U.S. 480 (2024)", "choices": [{"text": "A catch-all would make the rest of \u00a7 1512 unnecessary. The clause is tied to records, documents, and other evidence.", "ok": 1, "src": "model answer", "why": "Wins: says a catch-all would make the rest of \u00a7 1512 pointless, tied to evidence."}, {"text": "Okay, I see the point.", "ok": 0, "src": "common mistake", "why": "Loses: never says a catch-all would make the rest of \u00a7 1512 pointless; tied to evidence."}, {"text": "Congress didn't mean it.", "ok": 0, "src": "common mistake", "why": "Loses: never says a catch-all would make the rest of \u00a7 1512 pointless; tied to evidence."}]}, {"id": "fischer3", "case": "fed", "stage": "Motion to dismiss", "who": "judge", "say": "If I agree with you, what exactly are you asking me to do?", "say_real": false, "need": [{"k": "\"dismiss the count\"", "any": ["dismiss"]}, {"k": "Rule 12 / fails to state an offense", "any": ["rule 12", "12\\(b\\)", "fail(s|ure)? to state"]}], "avoid": [], "win": "COUNT DISMISSED", "lose": "THE COURT ASKS AGAIN", "model": "Dismiss that count under Rule 12(b)(3)(B)(v) because it fails to state an offense.", "why": "Always name the remedy and the rule. Judges grant what is asked for, in the form it's asked for.", "cite": "Fed. R. Crim. P. 12(b)(3)(B)(v)", "choices": [{"text": "Dismiss that count under Rule 12(b)(3)(B)(v) for failure to state an offense.", "ok": 1, "src": "model answer", "why": "Wins: says \"dismiss the count\", Rule 12 / fails to state an offense."}, {"text": "Just do what's fair, Your Honor.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"dismiss the count\"; Rule 12 / fails to state an offense."}, {"text": "Let me go home today.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"dismiss the count\"; Rule 12 / fails to state an offense."}]}], "real": "In June 2024 the Supreme Court vacated the D.C. Circuit's judgment and sent the case back. It held that \u00a7 1512(c)(2) requires proof that the defendant impaired, or tried to impair, the availability or integrity of records, documents, objects, or other things used in an official proceeding.", "cast": "c3"}, {"id": "zedner", "name": "Zedner v. United States", "cite": "547 U.S. 489 (2006)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/145651/zedner-v-united-states/", "verify": false, "charge": "Attempting to pass counterfeit financial instruments (federal court, New York)", "setup": "A man was charged in federal court in New York with trying to use fake multimillion-dollar bonds at banks. After several continuances, the judge had him sign a form waiving his Speedy Trial Act rights \"for all time.\" Years of delay followed before trial. You're the defendant moving to dismiss.", "role": "You are the defendant moving to dismiss under the Speedy Trial Act.", "cards": [{"id": "zedner1", "case": "fed", "stage": "Motion to dismiss", "who": "judge", "say": "You signed a waiver of your speedy trial rights \"for all time.\" Why isn't that the end of it?", "say_real": false, "need": [{"k": "can't prospectively waive", "any": ["cannot (prospectively )?waive", "can'?t (prospectively )?waive", "prospective"]}, {"k": "the public's interest too", "any": ["public", "society"]}, {"k": "Speedy Trial Act / \u00a7 3162", "any": ["3161", "3162", "speedy trial act"]}, {"k": "\"dismiss\"", "any": ["dismiss"]}], "avoid": [], "win": "MOTION TO DISMISS GRANTED", "lose": "MOTION DENIED", "model": "Your Honor, a defendant cannot prospectively waive the Speedy Trial Act. The Act protects the public's interest in prompt trials, not just mine, so my signature can't turn the clock off. I move to dismiss under 18 U.S.C. \u00a7 3162(a)(2).", "why": "Zedner held a blanket, advance waiver of the Act is not allowed. That's why you never have to sign one.", "cite": "Zedner v. United States, 547 U.S. 489, 500-503 (2006)", "choices": [{"text": "A defendant can't prospectively waive the Speedy Trial Act; it protects the public too. I move to dismiss under \u00a7 3162(a)(2).", "ok": 1, "src": "model answer", "why": "Wins: says can't prospectively waive, the public's interest too, Speedy Trial Act / \u00a7 3162, \"dismiss\"."}, {"text": "You're right, I signed it, so I'm stuck.", "ok": 0, "src": "common mistake", "why": "Loses: never says can't prospectively waive; the public's interest too; Speedy Trial Act / \u00a7 3162; \"dismiss\"."}, {"text": "I didn't read it before I signed.", "ok": 0, "src": "common mistake", "why": "Loses: never says can't prospectively waive; the public's interest too; Speedy Trial Act / \u00a7 3162; \"dismiss\"."}]}, {"id": "zedner2", "case": "fed", "stage": "Motion to dismiss", "who": "ausa", "say": "The judge granted an ends-of-justice continuance, so that time is excluded.", "say_real": false, "need": [{"k": "findings on the record", "any": ["on the record", "findings"]}, {"k": "\u00a7 3161(h) ends-of-justice", "any": ["3161\\(h\\)", "ends[- ]of[- ]justice"]}], "avoid": [], "win": "TIME NOT EXCLUDED", "lose": "TIME EXCLUDED", "model": "An ends-of-justice exclusion under \u00a7 3161(h) only counts if the judge made the findings and put them on the record, at the latest by the time of the motion to dismiss. There were no such findings here, so that time isn't excluded.", "why": "The Act requires the judge to set out reasons on the record. A continuance without findings doesn't stop the clock.", "cite": "Zedner, 547 U.S. at 506-507; 18 U.S.C. \u00a7 3161(h)(7)(A)", "choices": [{"text": "An ends-of-justice exclusion needs findings on the record. There were none, so the time isn't excluded.", "ok": 1, "src": "model answer", "why": "Wins: says findings on the record, \u00a7 3161(h) ends-of-justice."}, {"text": "Okay, then that time doesn't count.", "ok": 0, "src": "common mistake", "why": "Loses: never says findings on the record; \u00a7 3161(h) ends-of-justice."}, {"text": "The judge didn't like me.", "ok": 0, "src": "common mistake", "why": "Loses: never says findings on the record; \u00a7 3161(h) ends-of-justice."}]}, {"id": "zedner3", "case": "fed", "stage": "Motion to dismiss", "who": "ausa", "say": "Any error was harmless. The defendant got a fair trial in the end.", "say_real": false, "need": [{"k": "harmless error doesn't apply", "any": ["harmless[- ]error (review |analysis )?(doesn'?t|does not|can'?t|cannot)", "not harmless", "no harmless"]}, {"k": "the remedy is dismissal", "any": ["dismiss"]}], "avoid": [], "win": "MOTION GRANTED", "lose": "MOTION DENIED", "model": "Harmless-error review doesn't apply to a missing ends-of-justice finding. When the Act is violated, the remedy is dismissal; the only question left is with or without prejudice under \u00a7 3162(a)(2).", "why": "Zedner rejected the harmless-error argument for missing findings.", "cite": "Zedner, 547 U.S. at 507-509", "choices": [{"text": "Harmless error doesn't apply to missing findings. The remedy is dismissal under \u00a7 3162(a)(2).", "ok": 1, "src": "model answer", "why": "Wins: says harmless error doesn't apply, the remedy is dismissal."}, {"text": "I guess it was harmless then.", "ok": 0, "src": "common mistake", "why": "Loses: never says harmless error doesn't apply; the remedy is dismissal."}, {"text": "The trial wasn't fair because the jury was biased.", "ok": 0, "src": "common mistake", "why": "Loses: never says harmless error doesn't apply; the remedy is dismissal."}]}, {"id": "zedner4", "case": "fed", "stage": "Status conference (1996)", "who": "judge", "say": "I think if I'm going to give you that long an adjournment, I will have to take a waiver for all time.", "say_real": true, "say_src": "Zedner v. United States, 547 U.S. 489, 493-494 (2006) (district judge, quoted)", "need": [{"k": "\"no\"", "any": ["\\bno\\b"]}, {"k": "\"I do not waive\"", "any": ["not waive", "don'?t waive", "won'?t (sign|waive)"]}, {"k": "object / ask for findings", "any": ["object", "findings"]}], "avoid": [{"any": ["\\bI waive\\b", "\\bokay\\b", "that'?s fine"], "why": "That's a time waiver. Never."}], "win": "NO WAIVER", "lose": "TIME WAIVED", "model": "No, Your Honor. I do not waive time and I object to any exclusion. A defendant can't prospectively waive the Speedy Trial Act. If the Court considers an ends-of-justice continuance, I ask for findings on the record under \u00a7 3161(h)(7).", "why": "Say no, object, and if the judge goes ahead anyway, make the judge put findings on the record. Zedner makes those findings mandatory.", "cite": "Zedner, 547 U.S. 489; 18 U.S.C. \u00a7 3161(h)(7)", "choices": [{"text": "No. I do not waive time, I object to any exclusion, and I ask for findings on the record under \u00a7 3161(h)(7).", "ok": 1, "src": "model answer", "why": "Wins: says \"no\", \"I do not waive\", object / ask for findings."}, {"text": "[We] waive for all time. That will not be a problem. That will not be an issue in this case.", "ok": 0, "src": "real: Zedner's defense counsel, 547 U.S. at 494", "why": "A blanket waiver. It turned out to be legally void, but it came with years of delay and a trip to the Supreme Court."}, {"text": "Okay, if it helps.", "ok": 0, "src": "common mistake", "why": "That's a time waiver. Never."}, {"text": "I'll sign if it's only for a week.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"no\"; \"I do not waive\"; object / ask for findings."}]}], "real": "The Supreme Court unanimously held that a defendant can't prospectively waive the Speedy Trial Act, that an ends-of-justice continuance needs findings put on the record, and that harmless error doesn't excuse missing findings. It reversed and sent the case back for the trial court to decide whether to dismiss with or without prejudice.", "cast": "fed"}, {"id": "barker", "name": "Barker v. Wingo", "cite": "407 U.S. 514 (1972)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/108590/barker-v-wingo/", "verify": false, "charge": "Murder (Kentucky state court)", "setup": "In 1958 two men were arrested for a double murder in Kentucky. Prosecutors wanted to convict the other man first so he could testify against Barker, and kept continuing Barker's trial while that case went through several trials. Barker's trial was put off again and again for more than five years, and for years he didn't object. You're Barker.", "role": "You are the defendant.", "cards": [{"id": "barker1", "case": "state", "stage": "Another continuance", "who": "da", "say": "The Commonwealth moves to continue Mr. Barker's trial again until the co-defendant's case is finished.", "say_real": false, "need": [{"k": "\"I object\"", "any": ["\\bobject"]}, {"k": "demand a speedy trial", "any": ["speedy trial", "\\bdemand"]}, {"k": "constitutional right", "any": ["sixth amendment", "constitution"]}], "avoid": [{"any": ["no objection", "that'?s fine", "\\bI waive\\b"], "why": "Silence or agreement is exactly what sank Barker."}], "win": "DEMAND ON THE RECORD", "lose": "CONTINUANCE GRANTED WITHOUT OBJECTION", "model": "I object, Your Honor. I demand a speedy trial under the Sixth Amendment. I don't consent to this continuance, and I want my objection and my demand on the record.", "why": "In Barker, the years he didn't object counted heavily against him. Assert the right every time, out loud.", "cite": "Barker v. Wingo, 407 U.S. 514, 531-532 (1972)", "choices": [{"text": "I object. I demand a speedy trial under the Sixth Amendment and want that on the record.", "ok": 1, "src": "model answer", "why": "Wins: says \"I object\", demand a speedy trial, constitutional right."}, {"text": "No objection, as long as it gets done eventually.", "ok": 0, "src": "common mistake", "why": "Silence or agreement is exactly what sank Barker."}, {"text": "Whatever helps the Commonwealth.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"I object\"; demand a speedy trial; constitutional right."}]}, {"id": "barker2", "case": "state", "stage": "Quiz", "who": "quiz", "say": "What four factors does Barker v. Wingo weigh?", "say_real": false, "need": [{"k": "length of delay", "any": ["length"]}, {"k": "reason for delay", "any": ["reason"]}, {"k": "assertion of the right", "any": ["assert"]}, {"k": "prejudice", "any": ["prejudice"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "Length of the delay, the reason for the delay, whether and how the defendant asserted the right, and prejudice to the defendant.", "why": "No single factor decides it. That's why you build the record on every one of them.", "cite": "Barker, 407 U.S. at 530", "choices": [{"text": "Length of delay, reason for delay, the defendant's assertion of the right, and prejudice.", "ok": 1, "src": "model answer", "why": "Wins: says length of delay, reason for delay, assertion of the right, prejudice."}, {"text": "Length of delay, the judge's calendar, and the seriousness of the charge.", "ok": 0, "src": "common mistake", "why": "Loses: never says reason for delay; assertion of the right; prejudice."}, {"text": "Whether the defendant is in custody and whether he waived time once.", "ok": 0, "src": "common mistake", "why": "Loses: never says length of delay; reason for delay; assertion of the right; prejudice."}]}, {"id": "barker3", "case": "state", "stage": "Speedy-trial motion", "who": "judge", "say": "You let this go a long time without complaining. Why should I believe you want a speedy trial now?", "say_real": false, "need": [{"k": "asserting it now, on the record", "any": ["assert"]}, {"k": "name the prejudice", "any": ["prejudice", "anxiety", "memor", "witnesses"]}], "avoid": [{"any": ["\\bI waive\\b", "doesn'?t matter"], "why": "Don't undercut your own demand."}], "win": "DEMAND NOTED", "lose": "DEMAND DISCOUNTED", "model": "Your Honor, I'm asserting the right now, on the record, and I'll keep asserting it. The delay is prejudicing me: memories fade, witnesses get harder to find, and I live under the anxiety of an open charge.", "why": "Barker lists the kinds of prejudice courts look at: oppressive custody, anxiety, and damage to the defense. Name them.", "cite": "Barker, 407 U.S. at 532", "choices": [{"text": "I'm asserting it now, on the record. The delay is prejudicing me: fading memories, lost witnesses, and anxiety.", "ok": 1, "src": "model answer", "why": "Wins: says asserting it now, on the record, name the prejudice."}, {"text": "I guess it doesn't matter much now.", "ok": 0, "src": "common mistake", "why": "Don't undercut your own demand."}, {"text": "Because I'm tired of coming to court.", "ok": 0, "src": "common mistake", "why": "Loses: never says asserting it now, on the record; name the prejudice."}]}, {"id": "barker4", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Did Barker win his speedy-trial claim?", "say_real": false, "need": [{"k": "no", "any": ["\\bno\\b", "\\blost\\b"]}, {"k": "because he didn't want / assert a speedy trial", "any": ["didn'?t (want|assert|object)", "did not (want|assert|object)"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "No. The delay was long, but the Court found the prejudice was minimal and, most of all, the record showed he didn't want a speedy trial: he didn't object for years.", "why": "The lesson isn't the test. It's that silence loses.", "cite": "Barker, 407 U.S. at 533-536", "choices": [{"text": "No. The prejudice was minimal and he didn't want a speedy trial: he didn't object for years.", "ok": 1, "src": "model answer", "why": "Wins: says no, because he didn't want / assert a speedy trial."}, {"text": "Yes, five years is automatically too long.", "ok": 0, "src": "common mistake", "why": "Loses: never says no; because he didn't want / assert a speedy trial."}, {"text": "Yes, because the prosecution caused the delay.", "ok": 0, "src": "common mistake", "why": "Loses: never says no; because he didn't want / assert a speedy trial."}]}], "real": "The Supreme Court adopted a four-factor balancing test (length, reason, assertion, prejudice) and ruled against Barker. The delay of well over five years was extraordinary, but prejudice was minimal and he did not want a speedy trial, so his conviction stood.", "cast": "state"}, {"id": "brady", "name": "Brady v. Maryland", "cite": "373 U.S. 83 (1963)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/106598/brady-v-maryland/", "verify": false, "charge": "Murder in the first degree (Maryland state court)", "setup": "Brady and a companion were charged with a killing during a robbery in Maryland. Brady admitted taking part but said the companion did the actual killing. Before trial his lawyer asked for the companion's statements; the prosecution handed over some but held back one where the companion admitted to the killing. Brady was convicted and sentenced to death. You're Brady after the hidden statement comes out.", "role": "You are the defendant.", "cards": [{"id": "brady1", "case": "state", "stage": "Post-conviction", "who": "judge", "say": "Mr. Brady, the State says this statement wouldn't have changed the guilty verdict. Why does it matter?", "say_real": false, "need": [{"k": "favorable evidence was suppressed", "any": ["favorable"]}, {"k": "material to guilt OR punishment", "any": ["punishment", "sentenc"]}, {"k": "due process", "any": ["due process"]}], "avoid": [], "win": "RELIEF GRANTED", "lose": "RELIEF DENIED", "model": "Your Honor, the prosecution suppressed evidence favorable to me after I asked for it. That violates due process when the evidence is material either to guilt or to punishment. Even if it didn't change the verdict, it was material to whether I should be sentenced to death.", "why": "Brady's key move: materiality to punishment alone is enough.", "cite": "Brady v. Maryland, 373 U.S. 83, 87 (1963)", "choices": [{"text": "They suppressed favorable evidence I asked for. That violates due process if it's material to guilt or punishment, and it was material to my sentence.", "ok": 1, "src": "model answer", "why": "Wins: says favorable evidence was suppressed, material to guilt OR punishment, due process."}, {"text": "It doesn't matter, I was guilty anyway.", "ok": 0, "src": "common mistake", "why": "Loses: never says favorable evidence was suppressed; material to guilt OR punishment; due process."}, {"text": "The prosecutor is a bad person.", "ok": 0, "src": "common mistake", "why": "Loses: never says favorable evidence was suppressed; material to guilt OR punishment; due process."}]}, {"id": "brady2", "case": "state", "stage": "Post-conviction", "who": "da", "say": "The prosecutor acted in good faith. He didn't think the statement mattered.", "say_real": false, "need": [{"k": "good or bad faith doesn't matter", "any": ["bad faith", "regardless", "irrespective", "doesn'?t matter"]}, {"k": "suppression", "any": ["suppress", "withh(e|o)ld"]}], "avoid": [], "win": "ARGUMENT REJECTED", "lose": "ARGUMENT ACCEPTED", "model": "Under Brady, suppressing favorable, material evidence violates due process regardless of the good faith or bad faith of the prosecution.", "why": "The rule is about fairness to the accused, not punishing the prosecutor, so intent doesn't matter.", "cite": "Brady, 373 U.S. at 87", "choices": [{"text": "Suppressing favorable, material evidence violates due process regardless of good or bad faith.", "ok": 1, "src": "model answer", "why": "Wins: says good or bad faith doesn't matter, suppression."}, {"text": "Okay, if it was an honest mistake.", "ok": 0, "src": "common mistake", "why": "Loses: never says good or bad faith doesn't matter; suppression."}, {"text": "He knew exactly what he was doing.", "ok": 0, "src": "common mistake", "why": "Loses: never says good or bad faith doesn't matter; suppression."}]}, {"id": "brady4", "case": "state", "stage": "Quiz", "who": "quiz", "say": "What relief did Brady actually get?", "say_real": false, "need": [{"k": "new trial on punishment only", "any": ["punishment", "sentenc"]}, {"k": "the Supreme Court affirmed", "any": ["affirm"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "A new trial on punishment only, not on guilt. The Supreme Court affirmed that ruling from Maryland's highest court.", "why": "The statement couldn't have reduced the crime under Maryland law, so it mattered only to punishment.", "cite": "Brady, 373 U.S. at 88-91", "choices": [{"text": "A new trial on punishment only; the Supreme Court affirmed.", "ok": 1, "src": "model answer", "why": "Wins: says new trial on punishment only, the Supreme Court affirmed."}, {"text": "His conviction was thrown out and he went free.", "ok": 0, "src": "common mistake", "why": "Loses: never says new trial on punishment only; the Supreme Court affirmed."}, {"text": "Nothing; the Supreme Court said it was harmless.", "ok": 0, "src": "common mistake", "why": "Loses: never says new trial on punishment only; the Supreme Court affirmed."}]}], "real": "The Supreme Court affirmed Maryland's decision to give Brady a new trial limited to punishment. It held that the prosecution's suppression of evidence favorable to an accused who has asked for it violates due process when the evidence is material to guilt or to punishment, regardless of the prosecutor's good or bad faith.", "cast": "state"}, {"id": "rehaif", "name": "Rehaif v. United States", "cite": "588 U.S. 225 (2019)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/4632240/rehaif-v-united-states/", "verify": false, "charge": "Possessing a firearm while unlawfully in the U.S., 18 U.S.C. \u00a7\u00a7 922(g)(5), 924(a)(2)", "setup": "A man came to the U.S. on a student visa, was dismissed from his university, and stayed on. He later fired guns at a shooting range and was charged under the federal law that punishes someone who \"knowingly\" violates the ban on gun possession by people unlawfully in the country. The judge told the jury the government didn't have to prove he knew his status was unlawful. You're the defendant.", "role": "You are the defendant.", "cards": [{"id": "rehaif1", "case": "fed", "stage": "Jury-instruction conference", "who": "judge", "say": "Proposed instruction: the \"United States is not required to prove\" that the defendant \"knew that he was illegally or unlawfully in the United States.\" Any objection?", "say_real": true, "say_src": "Rehaif v. United States, 139 S. Ct. 2191, 2194 (2019) (instruction text verbatim; framing words added)", "need": [{"k": "\"I object\"", "any": ["\\bobject"]}, {"k": "\"knowingly\" covers status too", "any": ["status", "category"]}, {"k": "\"knowingly\"", "any": ["knowingly", "\\bknew\\b"]}], "avoid": [{"any": ["no objection"], "why": "Without an objection the error is reviewed only for plain error."}], "win": "INSTRUCTION CORRECTED", "lose": "INSTRUCTION GIVEN", "model": "Yes, Your Honor, I object. \"Knowingly\" applies to both parts: the government must prove I knew I possessed a firearm and that I knew I belonged to the category of people barred from having one.", "why": "Rehaif held the knowledge requirement applies to the status element, not just to possession.", "cite": "Rehaif v. United States, 588 U.S. 225 (2019)", "choices": [{"text": "I object. \"Knowingly\" applies to status too: they must prove I knew I was in the barred category.", "ok": 1, "src": "real: Rehaif objected to this instruction (139 S. Ct. at 2194); wording is the model answer", "why": "Wins: says \"I object\", \"knowingly\" covers status too, \"knowingly\"."}, {"text": "No objection, Your Honor.", "ok": 0, "src": "common mistake", "why": "Without an objection the error is reviewed only for plain error. (Rehaif did object, which is why he could win.)"}, {"text": "I didn't even know the gun was loaded.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"I object\"; \"knowingly\" covers status too; \"knowingly\"."}]}, {"id": "rehaif2", "case": "fed", "stage": "Jury-instruction conference", "who": "ausa", "say": "Ignorance of the law is no excuse, Your Honor.", "say_real": false, "need": [{"k": "this is about a fact (status), not the gun law", "any": ["status", "collateral", "\\bfact\\b"]}, {"k": "not claiming ignorance of the criminal law", "any": ["not (claiming|arguing) ignorance", "doesn'?t apply", "does not apply"]}], "avoid": [], "win": "OBJECTION SUSTAINED", "lose": "OBJECTION OVERRULED", "model": "That maxim doesn't apply here, Your Honor. I'm not claiming ignorance of the gun law. The question is whether I knew a fact, my own status, and a mistake about a collateral matter like that can negate the knowledge the statute requires.", "why": "Rehaif drew this line: not knowing a statute exists is no defense, but not knowing the facts (or a collateral legal status) that make you guilty can be.", "cite": "Rehaif, 588 U.S. 225 (2019)", "choices": [{"text": "That maxim doesn't apply. I'm not claiming ignorance of the gun law; the question is whether I knew my status, a fact.", "ok": 1, "src": "model answer", "why": "Wins: says this is about a fact (status), not the gun law, not claiming ignorance of the criminal law."}, {"text": "I didn't know it was illegal to have a gun.", "ok": 0, "src": "common mistake", "why": "That IS the 'ignorance of the law' defense, and it loses."}, {"text": "Nobody knows all the laws.", "ok": 0, "src": "common mistake", "why": "Loses: never says this is about a fact (status), not the gun law; not claiming ignorance of the criminal law."}], "trap": {"1": "That IS the 'ignorance of the law' defense, and it loses."}}, {"id": "rehaif4", "case": "fed", "stage": "Quiz", "who": "quiz", "say": "What did the Supreme Court do in Rehaif?", "say_real": false, "need": [{"k": "reversed", "any": ["revers"]}, {"k": "knowledge of status required", "any": ["status", "category"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "It reversed. The government must prove the defendant knew he had a gun and knew he belonged to the category of people barred from having one.", "why": "One word, \"knowingly,\" changed what the government had to prove.", "cite": "Rehaif, 588 U.S. 225 (2019)", "choices": [{"text": "Reversed: the government must prove he knew his status barred him.", "ok": 1, "src": "model answer", "why": "Wins: says reversed, knowledge of status required."}, {"text": "Affirmed: only knowing possession matters.", "ok": 0, "src": "common mistake", "why": "Loses: never says reversed; knowledge of status required."}, {"text": "Dismissed the case because of the visa.", "ok": 0, "src": "common mistake", "why": "Loses: never says reversed; knowledge of status required."}]}], "real": "The Supreme Court (7-2) reversed and sent the case back. In a \u00a7 922(g) prosecution the government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the category of persons barred from possessing one.", "cast": "c3"}, {"id": "windham", "name": "People v. Windham", "cite": "(1977) 19 Cal.3d 121", "court": "California Supreme Court", "url": "https://www.courtlistener.com/opinion/1222150/people-v-windham/", "verify": false, "charge": "Assault by means of force likely to produce great bodily injury, Pen. Code \u00a7 245(a)", "setup": "Windham was on trial for a beating outside a bar and claimed self-defense. He went to trial with a lawyer. Just before the third and last day of testimony he asked to fire his lawyer and represent himself, saying the lawyer kept mixing up names and wasn't drawing out the testimony that supported self-defense. The judge denied it mainly because it came too late. You're Windham making that midtrial request.", "role": "You are the defendant asking to represent yourself in the middle of trial.", "cards": [{"id": "windham1", "case": "state", "stage": "Midtrial Faretta request", "who": "judge", "say": "Mr. Windham, we're two days into testimony. Why should I let you take over now?", "say_real": false, "need": [{"k": "a specific reason", "any": ["testimony", "specific reason"]}, {"k": "no delay / ready now", "any": ["ready", "no delay", "not asking for (a|any) continuance"]}, {"k": "no disruption", "any": ["disrupt"]}], "avoid": [{"any": ["need (more )?time", "(want|need) a continuance"], "why": "Delay is the main reason judges deny late requests."}], "win": "REQUEST CONSIDERED", "lose": "REQUEST DENIED (untimely)", "model": "Your Honor, I have a specific reason: my lawyer hasn't brought out testimony that supports my defense and has confused the names of people in the case. I'm ready to proceed today, I'm not asking for any continuance, and I won't disrupt the trial. My lawyer can stay on as advisory counsel.", "why": "Once trial starts, the judge weighs the reasons, counsel's quality, the stage of trial and the likely delay or disruption. Answer every one of them.", "cite": "People v. Windham (1977) 19 Cal.3d 121, 128", "choices": [{"text": "I have a specific reason: key testimony isn't being brought out. I'm ready today, no continuance, and I won't disrupt the trial.", "ok": 1, "src": "model answer", "why": "Wins: says a specific reason, no delay / ready now, no disruption."}, {"text": "I just don't like him, and I'll need a week to catch up.", "ok": 0, "src": "common mistake", "why": "Loses: never says a specific reason; no delay / ready now; no disruption."}, {"text": "Because it's my right, period.", "ok": 0, "src": "common mistake", "why": "Loses: never says a specific reason; no delay / ready now; no disruption."}]}, {"id": "windham2", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Under Windham, when does a California defendant have an unconditional right to self-representation?", "say_real": false, "need": [{"k": "unequivocal", "any": ["unequivocal"]}, {"k": "a reasonable time before trial", "any": ["reasonable time", "before trial"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "When he makes an unequivocal request within a reasonable time before trial begins. After trial starts, it's up to the judge's discretion.", "why": "Early and unequivocal = a right. Late = a favor the judge may refuse.", "cite": "Windham, 19 Cal.3d at 127-128", "choices": [{"text": "When the request is unequivocal and made a reasonable time before trial.", "ok": 1, "src": "model answer", "why": "Wins: says unequivocal, a reasonable time before trial."}, {"text": "Any time, even during closing arguments.", "ok": 0, "src": "common mistake", "why": "Loses: never says unequivocal; a reasonable time before trial."}, {"text": "Only if the public defender agrees.", "ok": 0, "src": "common mistake", "why": "Loses: never says unequivocal; a reasonable time before trial."}]}, {"id": "windham3", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Name the Windham factors a judge weighs for a late request to go pro per.", "say_real": false, "need": [{"k": "quality of counsel", "any": ["quality"]}, {"k": "prior requests to substitute counsel", "any": ["proclivity", "substitut", "prior (requests|motions)"]}, {"k": "reasons for the request", "any": ["reason"]}, {"k": "length and stage of proceedings", "any": ["stage", "length"]}, {"k": "disruption or delay", "any": ["disrupt", "delay"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "The quality of counsel's representation, the defendant's prior proclivity to substitute counsel, the reasons for the request, the length and stage of the proceedings, and the disruption or delay that might follow.", "why": "If you ever ask late, address all five out loud so the record shows them.", "cite": "Windham, 19 Cal.3d at 128", "choices": [{"text": "Quality of counsel, prior proclivity to substitute counsel, the reasons, the length and stage of the case, and likely disruption or delay.", "ok": 1, "src": "model answer", "why": "Wins: says quality of counsel, prior requests to substitute counsel, reasons for the request, length and stage of proceedings, disruption or delay."}, {"text": "Whether the judge likes the defendant and how serious the charge is.", "ok": 0, "src": "common mistake", "why": "Loses: never says quality of counsel; prior requests to substitute counsel; reasons for the request; length and stage of proceedings; disruption or delay."}, {"text": "The defendant's education and whether he passed a legal test.", "ok": 0, "src": "common mistake", "why": "Loses: never says quality of counsel; prior requests to substitute counsel; reasons for the request; length and stage of proceedings; disruption or delay."}]}], "real": "The California Supreme Court affirmed the conviction. It held that a defendant must unequivocally assert the right to self-representation within a reasonable time before trial for it to be unconditional. Because Windham made no pretrial request, his midtrial request was up to the judge's discretion, weighing counsel's quality, prior substitution requests, the reasons, the stage of trial and likely disruption or delay.", "cast": "state"}, {"id": "williams", "name": "Williams v. Superior Court", "cite": "(1969) 71 Cal.2d 1144", "court": "California Supreme Court", "url": "https://www.courtlistener.com/opinion/1422837/williams-v-superior-court/", "verify": false, "charge": "Grand theft of an automobile (Pen. Code \u00a7 487) and receiving stolen property (Pen. Code \u00a7 496)", "setup": "A customized car was stolen and found the next day stripped of its custom parts. About eight weeks later the owner spotted another car of the same model carrying practically all of those parts, and Williams was arrested as he drove it off. At the preliminary hearing the prosecution offered no statements or other evidence that he knew the parts were stolen, but the magistrate held him to answer. His Penal Code 995 motion was denied, and he asked the California Supreme Court for a writ of prohibition. You're Williams.", "role": "You are the defendant attacking the preliminary-hearing evidence.", "cards": [{"id": "williams1", "case": "state", "stage": "PC 995 motion", "who": "judge", "say": "Mr. Williams, why should I set aside this information?", "say_real": false, "need": [{"k": "Penal Code 995", "any": ["995"]}, {"k": "\"without reasonable or probable cause\"", "any": ["probable cause", "sufficient cause"]}, {"k": "name the missing element (knowledge)", "any": ["\\bknew\\b", "knowledge", "knowing"]}], "avoid": [{"any": ["\\bI didn'?t know\\b", "\\bI bought\\b"], "why": "Don't testify through your motion. Argue what the record lacks."}], "win": "INFORMATION SET ASIDE", "lose": "MOTION DENIED", "model": "Your Honor, under Penal Code section 995 the information must be set aside because I was committed without reasonable or probable cause. There has to be some showing on every element, and the People offered nothing on knowledge: no statement, no conduct, nothing showing I knew the property was stolen.", "why": "A 995 motion asks whether the prelim record has some evidence on every element. Name the element that's missing.", "cite": "Pen. Code \u00a7 995; Williams v. Superior Court (1969) 71 Cal.2d 1144, 1147-1148", "choices": [{"text": "Under section 995, I was committed without reasonable or probable cause: there's no showing on knowledge, that I knew the property was stolen.", "ok": 1, "src": "model answer", "why": "Wins: says Penal Code 995, \"without reasonable or probable cause\", name the missing element (knowledge)."}, {"text": "I didn't know the parts were stolen, I bought them from a guy.", "ok": 0, "src": "common mistake", "why": "That's testifying, and it can be used against you. Argue the gap in their evidence instead."}, {"text": "The magistrate was wrong and unfair.", "ok": 0, "src": "common mistake", "why": "Loses: never says Penal Code 995; \"without reasonable or probable cause\"; name the missing element (knowledge)."}], "trap": {"1": "That's testifying, and it can be used against you. Argue the gap in their evidence instead."}}, {"id": "williams2", "case": "state", "stage": "Preliminary hearing ruling", "who": "judge", "say": "Maybe there were other seat covers like this; maybe there are other wheels like this... but were they all on the same car? There is enough to hold him.", "say_real": true, "say_src": "Williams v. Superior Court (1969) 71 Cal.2d 1144, 1146-1147 (magistrate, quoted)", "need": [{"k": "possession alone isn't enough", "any": ["mere possession", "possession alone", "possession,? by itself"]}, {"k": "attack the inference", "any": ["infer"]}], "avoid": [{"any": ["\\bI didn'?t know\\b", "\\bI bought\\b"], "why": "Argue the record, not your story."}], "win": "ARGUMENT PRESERVED", "lose": "ARGUMENT WAIVED", "model": "Mere possession, by itself, isn't evidence of knowledge. The People need some other circumstance from which the magistrate could reasonably infer that I knew, and here there's nothing but possession.", "why": "This is the right argument to make, even though Williams lost it: the court found the 'whole set of parts together' detail was enough for an inference.", "cite": "Williams, 71 Cal.2d at 1149-1151", "choices": [{"text": "Mere possession, by itself, isn't evidence of knowledge. There's no other circumstance to infer that I knew.", "ok": 1, "src": "real: Williams's argument (71 Cal.2d at 1149); wording is the model answer", "why": "Wins: says possession alone isn't enough, attack the inference."}, {"text": "I didn't know, I bought those parts.", "ok": 0, "src": "common mistake", "why": "Argue the record, not your story."}, {"text": "That's just their opinion.", "ok": 0, "src": "common mistake", "why": "Loses: never says possession alone isn't enough; attack the inference."}]}, {"id": "williams3", "case": "state", "stage": "Quiz", "who": "quiz", "say": "What's the standard to hold someone to answer at a California preliminary hearing?", "say_real": false, "need": [{"k": "strong suspicion", "any": ["strong suspicion"]}, {"k": "a person of ordinary caution or prudence", "any": ["ordinary caution", "prudence"]}, {"k": "less than needed to convict", "any": ["less than", "need not", "not (enough|sufficient) to convict"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "Sufficient cause: facts that would lead a person of ordinary caution or prudence to entertain a strong suspicion of guilt. It's much less than what's needed to convict.", "why": "Knowing the low bar keeps you realistic: win a 995 by showing a missing element, not by arguing reasonable doubt.", "cite": "Williams, 71 Cal.2d at 1147; Pen. Code \u00a7 872", "choices": [{"text": "Facts leading a person of ordinary caution or prudence to a strong suspicion of guilt, much less than needed to convict.", "ok": 1, "src": "model answer", "why": "Wins: says strong suspicion, a person of ordinary caution or prudence, less than needed to convict."}, {"text": "Proof beyond a reasonable doubt.", "ok": 0, "src": "common mistake", "why": "Loses: never says strong suspicion; a person of ordinary caution or prudence; less than needed to convict."}, {"text": "Any accusation by a police officer.", "ok": 0, "src": "common mistake", "why": "Loses: never says strong suspicion; a person of ordinary caution or prudence; less than needed to convict."}]}, {"id": "williams4", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Did Williams win his writ?", "say_real": false, "need": [{"k": "no", "any": ["\\bno\\b", "denied"]}, {"k": "knowledge inferred from circumstances", "any": ["infer", "circumstan"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "No. The court said having practically all the parts from one stolen car, together on another car within weeks, let the magistrate reasonably infer he was the thief or knew they were stolen.", "why": "Knowledge can be proven by circumstances, so look for which circumstances are actually in the record.", "cite": "Williams, 71 Cal.2d at 1150-1151", "choices": [{"text": "No. The circumstances let the magistrate reasonably infer knowledge.", "ok": 1, "src": "model answer", "why": "Wins: says no, knowledge inferred from circumstances."}, {"text": "Yes, because possession is never enough.", "ok": 0, "src": "common mistake", "why": "Loses: never says no; knowledge inferred from circumstances."}, {"text": "Yes, the case was dismissed for delay.", "ok": 0, "src": "common mistake", "why": "Loses: never says no; knowledge inferred from circumstances."}]}], "real": "The California Supreme Court denied the writ. It restated the rule: an information must be set aside under section 995 if the defendant was held without reasonable or probable cause, meaning facts that support a strong suspicion of guilt with some showing on every element, though circumstantial evidence and reasonable inferences count. Finding practically all the parts from one stolen car together on another car weeks later let the magistrate infer guilty knowledge.", "cast": "state"}, {"id": "frye", "name": "Missouri v. Frye", "cite": "566 U.S. 134 (2012)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/626055/missouri-v-frye/", "verify": false, "charge": "Driving with a revoked license (a felony because of prior offenses), Missouri state court", "setup": "Frye was charged with driving on a revoked license, a felony because of his record. The prosecutor mailed his lawyer a letter with two plea offers that would expire on a set date, one reducing the charge to a misdemeanor. The lawyer never told him and the offers expired. Before his preliminary hearing he was arrested again for the same thing, and he later pleaded guilty with no deal and got three years. You're Frye at the post-conviction hearing.", "role": "You are the defendant (post-conviction).", "cards": [{"id": "frye1", "case": "state", "stage": "Post-conviction hearing", "who": "judge", "say": "Your lawyer didn't tell you about the offer. So what? You pleaded guilty anyway.", "say_real": false, "need": [{"k": "duty to communicate formal offers", "any": ["communicat", "formal offer"]}, {"k": "ineffective assistance / Sixth Amendment", "any": ["ineffective", "sixth amendment"]}, {"k": "reasonable probability I'd have accepted", "any": ["reasonable probability", "would have accepted"]}], "avoid": [], "win": "CLAIM HEARD", "lose": "CLAIM DENIED", "model": "Your Honor, defense counsel has a duty to communicate formal plea offers that may be favorable. Not doing it is ineffective assistance under the Sixth Amendment. And there's a reasonable probability I would have accepted the misdemeanor offer.", "why": "Frye made the duty to communicate formal offers part of the Sixth Amendment right to counsel.", "cite": "Missouri v. Frye, 566 U.S. 134, 145 (2012)", "choices": [{"text": "Counsel had to communicate the formal offer. Not doing it is ineffective assistance, and there's a reasonable probability I would have accepted.", "ok": 1, "src": "model answer", "why": "Wins: says duty to communicate formal offers, ineffective assistance / Sixth Amendment, reasonable probability I'd have accepted."}, {"text": "My lawyer was lazy.", "ok": 0, "src": "common mistake", "why": "Loses: never says duty to communicate formal offers; ineffective assistance / Sixth Amendment; reasonable probability I'd have accepted."}, {"text": "I should get a new lawyer.", "ok": 0, "src": "common mistake", "why": "Loses: never says duty to communicate formal offers; ineffective assistance / Sixth Amendment; reasonable probability I'd have accepted."}]}, {"id": "frye2", "case": "state", "stage": "Post-conviction hearing", "who": "da", "say": "Even if he'd said yes, the prosecutor could have pulled the offer or the judge could have rejected it.", "say_real": false, "need": [{"k": "\"reasonable probability\"", "any": ["reasonable probability"]}, {"k": "the plea would have gone through", "any": ["(wouldn'?t|would not) have (been )?(withdrawn|cancel|reject)", "without the (prosecution|state|prosecutor) cancel", "court would have accepted", "entered"]}], "avoid": [], "win": "ARGUMENT NOTED", "lose": "ARGUMENT ACCEPTED", "model": "The test is a reasonable probability that I would have accepted the offer and that the plea would have been entered without the prosecution canceling it or the court refusing it. I'll show both.", "why": "Frye set out the prejudice test for a lapsed offer: acceptance, plus it actually going through.", "cite": "Frye, 566 U.S. at 147", "choices": [{"text": "The test is a reasonable probability I'd have accepted and the plea would have been entered without being canceled or refused.", "ok": 1, "src": "model answer", "why": "Wins: says \"reasonable probability\", the plea would have gone through."}, {"text": "They wouldn't have cared.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"reasonable probability\"; the plea would have gone through."}, {"text": "That's just speculation, Your Honor.", "ok": 0, "src": "common mistake", "why": "Loses: never says \"reasonable probability\"; the plea would have gone through."}]}, {"id": "frye3", "case": "state", "stage": "Quiz", "who": "quiz", "say": "What made prejudice hard for Frye to prove?", "say_real": false, "need": [{"k": "he was arrested again", "any": ["arrest(ed)? again", "new arrest", "re-?arrest"]}, {"k": "the offer might not have survived", "any": ["withdr", "cancel", "reject", "not (have )?accept"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "He was arrested again for driving on a revoked license before the plea could have gone through, which raised doubt: the prosecutor might have withdrawn the offer, or the court might have rejected the plea.", "why": "New conduct while a case is pending can cost you deals you'd otherwise have.", "cite": "Frye, 566 U.S. at 151", "choices": [{"text": "He was arrested again, so the prosecutor might have withdrawn the offer or the court rejected it.", "ok": 1, "src": "model answer", "why": "Wins: says he was arrested again, the offer might not have survived."}, {"text": "He had already pleaded guilty.", "ok": 0, "src": "common mistake", "why": "Loses: never says he was arrested again; the offer might not have survived."}, {"text": "The offer wasn't in writing.", "ok": 0, "src": "common mistake", "why": "Loses: never says he was arrested again; the offer might not have survived."}]}, {"id": "frye4", "case": "fed", "stage": "Quiz", "who": "quiz", "say": "Why do judges now put plea offers on the record at hearings?", "say_real": false, "need": [{"k": "to show the offer was communicated", "any": ["communicat", "was told", "received"]}, {"k": "on the record", "any": ["record", "writing"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "After Frye, courts and prosecutors put formal offers in writing or on the record so it's clear the offer was communicated and nobody can later claim it wasn't.", "why": "When the judge asks if you got the offer, just confirm it and stop. No discussion of the facts.", "cite": "Frye, 566 U.S. at 146", "choices": [{"text": "To make a record that the offer was communicated to the defendant.", "ok": 1, "src": "model answer", "why": "Wins: says to show the offer was communicated, on the record."}, {"text": "To pressure the defendant to plead.", "ok": 0, "src": "common mistake", "why": "Loses: never says to show the offer was communicated; on the record."}, {"text": "Because the judge decides the sentence.", "ok": 0, "src": "common mistake", "why": "Loses: never says to show the offer was communicated; on the record."}]}], "real": "The Supreme Court (5-4) held that defense counsel generally must communicate formal plea offers and that Frye's lawyer's failure was deficient performance. But it sent the case back on prejudice, because his new arrest raised doubt that the prosecution would have kept the deal or the court would have accepted it.", "cast": "state"}, {"id": "allen", "name": "Illinois v. Allen", "cite": "397 U.S. 337 (1970)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/108110/illinois-v-allen/", "verify": false, "charge": "Armed robbery (Illinois state court)", "setup": "Allen was on trial in Illinois for robbing a tavern at gunpoint. During jury selection he started questioning jurors himself, argued with the judge in an abusive way, threatened the judge, and threw his lawyer's papers on the floor. After warnings he was removed, and most of the prosecution's case went on without him. You're Allen, standing in front of a judge who has just warned you.", "role": "You are the defendant (courtroom conduct).", "cards": [{"id": "allen1", "case": "state", "stage": "Jury selection", "who": "judge", "say": "One more outbreak of that sort and I'll remove you from the courtroom.", "say_real": true, "say_src": "Illinois v. Allen, 397 U.S. 337, 340 (1970) (trial judge, quoted)", "need": [{"k": "apologize", "any": ["apolog", "\\bsorry\\b"]}, {"k": "\"Your Honor\"", "any": ["your honor"]}, {"k": "promise to conduct yourself properly", "any": ["conduct myself", "behave", "follow the (court'?s )?rules"]}], "avoid": [{"any": ["no trial", "no proceeding", "keep on talking", "\\bunfair\\b"], "why": "Defiance is exactly what gets a defendant removed from his own trial."}], "win": "YOU STAY IN THE COURTROOM", "lose": "REMOVED FROM THE COURTROOM", "model": "I apologize, Your Honor. I'll conduct myself properly and follow the Court's rules. I want to stay present for my trial.", "why": "Allen says a warned defendant who keeps disrupting can lose his right to be present. A short apology and a promise keeps you in the room, and in pro per status.", "cite": "Illinois v. Allen, 397 U.S. 337, 343 (1970)", "choices": [{"text": "I apologize, Your Honor. I'll conduct myself properly and follow the Court's rules.", "ok": 1, "src": "model answer", "why": "Takes the warning seriously and keeps your right to be present."}, {"text": "There's not going to be no trial, either.", "ok": 0, "src": "real: Allen, 397 U.S. at 340", "why": "Allen said this and was removed; the Supreme Court upheld the removal."}, {"text": "This whole thing is unfair, Your Honor.", "ok": 0, "src": "common mistake", "why": "Arguing with the warning invites the removal."}]}, {"id": "allen2", "case": "state", "stage": "After the lunch recess", "who": "judge", "say": "You may stay in the courtroom as long as you behave yourself and don't interfere with the presentation of the case.", "say_real": false, "say_src": "Paraphrase of the judge's condition reported in Allen, 397 U.S. at 340", "need": [{"k": "agree to behave", "any": ["behave", "conduct myself", "won'?t interfere", "will not interfere"]}, {"k": "ask to be present", "any": ["present", "stay"]}, {"k": "raise disagreements the proper way", "any": ["object", "motion", "on the record"]}], "avoid": [{"any": ["no proceeding", "keep on talking", "no trial"], "why": "Announcing you'll keep disrupting gets you removed."}], "win": "YOU STAY", "lose": "REMOVED AGAIN", "model": "Understood, Your Honor. I will behave and I won't interfere. I want to be present, and I'll raise any disagreement by objecting on the record or by motion.", "why": "Every complaint has a proper channel: an objection, a motion, or a request to be heard. Use those, not interruptions.", "cite": "Allen, 397 U.S. at 343", "choices": [{"text": "Understood. I'll behave and won't interfere. I want to stay present, and I'll object on the record when I disagree.", "ok": 1, "src": "model answer", "why": "Keeps you in the room and keeps your objections alive."}, {"text": "There is going to be no proceeding. I'm going to start talking and I'm going to keep on talking all through the trial.", "ok": 0, "src": "real: Allen, 397 U.S. at 340-341", "why": "Allen said this and was removed for the prosecution's case."}, {"text": "Fine, but my lawyer is useless.", "ok": 0, "src": "common mistake", "why": "Attacking counsel in front of the jury helps nobody and never asks for anything the court can grant."}]}, {"id": "allen3", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Under Illinois v. Allen, what can a judge do with a defendant who keeps disrupting the trial?", "say_real": false, "need": [{"k": "bind and gag", "any": ["gag", "bind", "shackl"]}, {"k": "contempt", "any": ["contempt"]}, {"k": "remove him until he promises to behave", "any": ["remov"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "Bind and gag him as a last resort, cite him for contempt, or remove him from the courtroom until he promises to conduct himself properly.", "why": "Removal is reversible: the right to be present comes back once you promise to behave.", "cite": "Allen, 397 U.S. at 343-344", "choices": [{"text": "Bind and gag him, hold him in contempt, or remove him until he promises to behave.", "ok": 1, "src": "model answer", "why": "Those are the three options Allen lists."}, {"text": "Nothing; he always has a right to be present.", "ok": 0, "src": "common mistake", "why": "Allen holds the right can be lost by persistent disruption after a warning."}, {"text": "Dismiss the case.", "ok": 0, "src": "common mistake", "why": "Disruption never wins the defendant a dismissal."}]}, {"id": "allen4", "case": "state", "stage": "Quiz", "who": "quiz", "say": "Did Allen win in the Supreme Court?", "say_real": false, "need": [{"k": "no", "any": ["\\bno\\b", "\\blost\\b"]}, {"k": "disruption after a warning", "any": ["warn"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "No. The Court held that he lost his right to be present by continuing his disruptive conduct after the judge warned him he would be removed.", "why": "The warning is the turning point. After it, the next outburst can cost you your seat at your own trial.", "cite": "Allen, 397 U.S. at 343, 346", "choices": [{"text": "No. He lost his right to be present by continuing to disrupt after the judge warned him.", "ok": 1, "src": "model answer", "why": "That's the holding."}, {"text": "Yes, removal is never allowed.", "ok": 0, "src": "common mistake", "why": "Wrong: removal after warnings was upheld."}, {"text": "Yes, because the judge was rude to him.", "ok": 0, "src": "common mistake", "why": "Wrong: the Court praised the judge's patience."}]}], "real": "The Supreme Court reversed the court of appeals, which had granted Allen relief. It held a defendant can lose his right to be present at trial if, after being warned he will be removed, he keeps up disruptive conduct; he can get it back by promising to conduct himself properly. Judges may also use contempt or, as a last resort, binding and gagging.", "cast": "state"}, {"id": "erskine", "name": "United States v. Erskine", "cite": "355 F.3d 1161 (9th Cir. 2004)", "court": "U.S. Court of Appeals, Ninth Circuit", "url": "https://www.courtlistener.com/opinion/784847/united-states-v-erik-d-erskine/", "verify": false, "charge": "Threatening federal officials, 18 U.S.C. \u00a7 115(a)(1)(B) (C.D. Cal.)", "setup": "Erskine believed the FBI was corrupt and his life was in danger, and he contacted FBI agents in Santa Maria, California, and other agencies. He was charged in federal court in the Central District of California. After a first trial ended with an acquittal on one count and a hung jury on the other, he asked to represent himself. The judge held a long Faretta colloquy. You're Erskine at that hearing, in the same district as your own case.", "role": "You are the defendant asking to represent yourself.", "cards": [{"id": "erskine1", "case": "fed", "stage": "Faretta hearing", "who": "judge", "say": "All right. With respect to the possible sentences, do you know what that is?", "say_real": true, "say_src": "United States v. Erskine, 355 F.3d 1161, 1164-1165 (9th Cir. 2004) (district judge, quoted)", "need": [{"k": "the correct statutory maximum (5 years)", "any": ["five years", "\\b5 years"]}, {"k": "\"statutory maximum\"", "any": ["maximum"]}, {"k": "the statute", "any": ["\\b115\\b"]}], "avoid": [{"any": ["one year", "zero to six months", "maximum (amount )?is listed through the guidelines"], "why": "The guidelines range is not the statutory maximum. Getting the max wrong can make the whole waiver invalid."}], "win": "WAIVER IS KNOWING", "lose": "WAIVER BUILT ON A WRONG NUMBER", "model": "Yes, Your Honor. The statutory maximum under 18 U.S.C. \u00a7 115(b)(4) is five years in prison per count. I understand the guidelines range is not the maximum.", "why": "A Faretta waiver must be made knowing the possible penalties. Say the statutory maximum yourself, correctly, and don't confuse it with the guidelines.", "cite": "Erskine, 355 F.3d at 1165, 1167-1169", "choices": [{"text": "Yes, Your Honor. The statutory maximum under \u00a7 115 is five years per count. The guidelines range is not the maximum.", "ok": 1, "src": "model answer", "why": "States the real maximum, so the waiver is knowing."}, {"text": "One, sir. Maximum amount is one year. My sentencing guidelines, though, is zero to six months because of my offense level.", "ok": 0, "src": "real: Erskine, 355 F.3d at 1165", "why": "Wrong maximum (it was five years). The judge said 'All right,' and the conviction was later reversed because of it."}, {"text": "I'm not sure, but it can't be that much.", "ok": 0, "src": "common mistake", "why": "Not knowing the maximum means the waiver isn't knowing."}]}, {"id": "erskine2", "case": "fed", "stage": "Arraignment on superseding indictment", "who": "ausa", "say": "The correct maximum penalty in this case... is a maximum of five years of imprisonment, and I just wanted to make sure that everybody was on the same page, especially since Mr. Erskine is representing himself in this case.", "say_real": true, "say_src": "Erskine, 355 F.3d at 1165 (AUSA, quoted)", "need": [{"k": "five years", "any": ["five years", "\\b5 years"]}, {"k": "ask to be re-advised / reconsider the waiver", "any": ["re-?advise", "reconsider", "again", "withdraw"]}, {"k": "the waiver of counsel", "any": ["waiver", "counsel", "represent"]}], "avoid": [], "win": "WAIVER REVISITED ON THE RECORD", "lose": "WAIVER STANDS ON BAD INFORMATION", "model": "Your Honor, when I waived counsel I understood the maximum to be one year. Now that it's five years, I ask the Court to re-advise me and let me decide again whether to keep representing myself.", "why": "When the stakes change, the record should show you chose again knowing the real numbers. In Erskine the court just said 'All right' and moved on, and that error cost the government the conviction.", "cite": "Erskine, 355 F.3d at 1165, 1169-1170", "choices": [{"text": "Your Honor, I waived counsel thinking the max was one year. Now that it's five years, please re-advise me and let me decide again about representing myself.", "ok": 1, "src": "model answer", "why": "Fixes the record so any waiver is truly knowing."}, {"text": "Okay, let's keep going.", "ok": 0, "src": "common mistake", "why": "Lets a waiver built on the wrong number stand without a word."}, {"text": "Five years? That's ridiculous for a phone call.", "ok": 0, "src": "common mistake", "why": "Arguing the facts in open court helps the government and asks for nothing."}]}, {"id": "erskine3", "case": "fed", "stage": "Faretta hearing", "who": "judge", "say": "One who represents himself has a fool for a client. I'm sure you've heard that before.", "say_real": true, "say_src": "Erskine, 355 F.3d at 1164 n.4 (district judge, quoted)", "need": [{"k": "\"dangers and disadvantages\"", "any": ["danger", "disadvantage", "risk"]}, {"k": "knowingly and intelligently", "any": ["knowing", "intelligent"]}, {"k": "\"I still choose\"", "any": ["\\bstill\\b"]}], "avoid": [{"any": ["\\bfool\\b", "cut me (some )?slack"], "why": "Don't trade jokes or insults with the bench, and don't ask for slack."}], "win": "REQUEST STANDS", "lose": "REQUEST DENIED", "model": "I have, Your Honor. I understand the dangers and disadvantages of representing myself, and I'm waiving counsel knowingly and intelligently. I still choose to represent myself.", "why": "The judge will try to talk you out of it. That's his job. Answer with the legal words and stay calm.", "cite": "Erskine, 355 F.3d at 1167-1169; Faretta, 422 U.S. at 835", "choices": [{"text": "I understand the dangers and disadvantages, and I'm waiving counsel knowingly and intelligently. I still choose to represent myself.", "ok": 1, "src": "model answer", "why": "Puts the three key ideas on the record."}, {"text": "Then I guess I'm a fool.", "ok": 0, "src": "common mistake", "why": "Sounds equivocal and gives the judge nothing to rely on."}, {"text": "Maybe I'll keep my lawyer for now.", "ok": 0, "src": "common mistake", "why": "Equivocal: the request can be treated as withdrawn."}]}, {"id": "erskine4", "case": "fed", "stage": "Quiz", "who": "quiz", "say": "Why did the Ninth Circuit reverse Erskine's conviction?", "say_real": false, "need": [{"k": "the maximum penalty was never correctly explained", "any": ["penalt", "maximum"]}, {"k": "the waiver wasn't knowing and intelligent", "any": ["knowing", "intelligent"]}], "avoid": [], "win": "CORRECT", "lose": "WRONG", "model": "Because the court never correctly advised him of the maximum penalty, and the record didn't show he understood it, so his waiver of counsel was not knowing and intelligent.", "why": "A Faretta waiver needs three things understood: the charges, the possible penalties, and the dangers of self-representation.", "cite": "Erskine, 355 F.3d at 1167-1171", "choices": [{"text": "The court never correctly told him the maximum penalty, so his waiver wasn't knowing and intelligent.", "ok": 1, "src": "model answer", "why": "That's the holding."}, {"text": "Because self-representation is never allowed for threat charges.", "ok": 0, "src": "common mistake", "why": "Wrong: the right exists for every charge."}, {"text": "Because the jury was hung the first time.", "ok": 0, "src": "common mistake", "why": "Irrelevant to the reversal."}]}], "real": "The Ninth Circuit reversed and remanded in 2004. The judge never correctly told Erskine the five-year maximum, and the record didn't show he understood it, so his waiver of counsel was not knowing and intelligent. That error required reversal of the conviction.", "cast": "fed"}, {"id": "alford", "name": "North Carolina v. Alford", "cite": "400 U.S. 25 (1970)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/108215/north-carolina-v-alford/", "verify": false, "charge": "First-degree murder, pleaded down to second-degree murder (North Carolina state court)", "setup": "In 1963 Alford was indicted for first-degree murder, which was a capital offense in North Carolina. His court-appointed lawyer interviewed the witnesses Alford said would help him, but their statements pointed strongly toward guilt, so the lawyer recommended pleading guilty to second-degree murder and left the decision to Alford. At the plea hearing the State put on its evidence. Alford then testified that he hadn't done the killing and was pleading only to avoid the death penalty. You're Alford, and the judge has to decide whether to take your plea.", "role": "You are the defendant pleading guilty while saying you are innocent.", "cards": [{"id": "alford1", "case": "state", "stage": "Plea hearing (after the State's evidence)", "who": "judge", "say": "You've just told me you didn't do this. Knowing that, do you still want to plead guilty to second-degree murder?", "say_real": false, "need": [{"k": "a clear yes", "any": ["\\byes\\b", "still (want|wish|desire) to plead guilty"]}, {"k": "why the plea makes sense to you", "any": ["evidence", "death penalty", "\\brisk\\b"]}, {"k": "your own voluntary choice", "any": ["voluntar(y|ily)", "my own (choice|decision)", "own (free )?(will|volition)"]}], "avoid": [{"any": ["you all got me", "\\b(made|forced|told) me to\\b", "because (he|they) said"], "why": "Blaming the decision on someone else makes the plea sound coerced, not voluntary."}], "win": "PLEA ACCEPTED", "lose": "PLEA IN DOUBT (sounds coerced)", "model": "Yes, Your Honor. I still want to plead guilty to second-degree murder. I say I'm innocent, but the evidence against me is strong and I don't want to risk the death penalty at trial. This is my own voluntary decision after talking it over with my lawyer and my family.", "why": "The judge asked Alford whether he still wanted to plead guilty even though he denied guilt, and he said yes, but he tied it to what his lawyer had told him. The Supreme Court upheld the plea because the record showed a strong case and a clearly expressed choice. Saying clearly that the choice is yours, and why, is what makes the plea hold up.", "cite": "North Carolina v. Alford, 400 U.S. 25 (1970)", "choices": [{"text": "Yes. I say I'm innocent, but the evidence is strong and I won't risk the death penalty. It's my own voluntary decision.", "ok": 1, "src": "model answer", "why": "Wins: a clear yes, why the plea makes sense to you, and your own voluntary choice."}, {"text": "Well, I'm pleading because my lawyer told me to plead guilty.", "ok": 0, "src": "common mistake", "why": "Blaming the decision on someone else makes the plea sound coerced, not voluntary."}, {"text": "Yes. Let's just get this over with.", "ok": 0, "src": "common mistake", "why": "A bare yes says nothing about why you're choosing this or that it's your own decision, so the record is thin."}, {"text": "No. I didn't do it.", "ok": 0, "src": "common mistake", "why": "That's a fine answer if you want a trial, but it isn't a plea. The judge will set the case for trial."}], "trap": {"1": "Blaming the decision on someone else makes the plea sound coerced, not voluntary."}}, {"id": "alford2", "case": "state", "stage": "Plea hearing (your rights)", "who": "judge", "say": "Has your lawyer explained the difference between first- and second-degree murder, and the rights you'd have if you went to trial?", "say_real": false, "need": [{"k": "you understand", "any": ["understand"]}, {"k": "the trial rights you give up", "any": ["jury", "\\btrial\\b"]}, {"k": "your lawyer explained it", "any": ["lawyer", "attorney", "counsel"]}], "avoid": [{"any": ["\\bI guess\\b", "\\bnot sure\\b", "\\bkind of\\b", "\\bsort of\\b"], "why": "An unsure answer tells the judge you may not understand what you're giving up."}], "win": "RIGHTS CONFIRMED", "lose": "COLLOQUY STALLS (unsure)", "model": "Yes, Your Honor. My lawyer explained the difference between first- and second-degree murder, and I understand I'm giving up my right to a jury trial.", "why": "Alford confirmed that his lawyer had explained the two degrees of murder and his rights if he went to trial. A plea has to be knowing, so the judge needs to hear that you understand what you're giving up.", "cite": "North Carolina v. Alford, 400 U.S. 25 (1970)", "choices": [{"text": "Yes. My lawyer explained both charges, and I understand I'm giving up a jury trial.", "ok": 1, "src": "model answer", "why": "Wins: you understand, you name the trial rights you give up, and you say your lawyer explained it."}, {"text": "I guess so. He talked about it some.", "ok": 0, "src": "common mistake", "why": "An unsure answer tells the judge you may not understand what you're giving up."}, {"text": "Yes, sir.", "ok": 0, "src": "common mistake", "why": "Safe, but it doesn't show the judge you know which rights you're giving up."}], "trap": {"1": "An unsure answer tells the judge you may not understand what you're giving up."}}, {"id": "alford3", "case": "state", "stage": "Plea hearing (protesting innocence)", "who": "quiz", "say": "I don't\u2014I'm not guilty but I plead guilty.", "say_real": true, "say_src": "North Carolina v. Alford, 400 U.S. 25, n.2 (1970) (Alford, answering his lawyer's questions at the plea hearing)", "need": [{"k": "a voluntary and intelligent choice", "any": ["voluntar(y|ily)", "intelligent"]}, {"k": "a strong factual basis for guilt", "any": ["factual basis", "strong (evidence|case)", "evidence (is |was )?strong"]}], "avoid": [{"any": ["must (admit|confess)", "never accept", "automatically (void|invalid)"], "why": "The Constitution doesn't require you to admit guilt before a judge can accept your guilty plea."}], "win": "YOU KNOW THE RULE", "lose": "WRONG RULE", "model": "The judge can accept it if the plea is a voluntary and intelligent choice among the options and the record shows a strong factual basis for guilt.", "why": "This is the \"Alford plea.\" The Court said a defendant can choose to plead guilty without admitting the crime when he intelligently decides it's in his interest and the record strongly shows guilt.", "cite": "North Carolina v. Alford, 400 U.S. 25 (1970)", "choices": [{"text": "The judge can accept it if it's a voluntary and intelligent choice and there's a strong factual basis for guilt.", "ok": 1, "src": "model answer", "why": "Wins: a voluntary and intelligent choice, plus a strong factual basis for guilt."}, {"text": "The defendant must admit guilt out loud, or the plea is no good.", "ok": 0, "src": "common mistake", "why": "The Constitution doesn't require you to admit guilt before a judge can accept your guilty plea."}, {"text": "Any plea counts as long as the defendant signs the form.", "ok": 0, "src": "common mistake", "why": "Signing a form isn't enough. The judge still has to see a real choice and a strong case on the record."}], "trap": {"1": "The Constitution doesn't require you to admit guilt before a judge can accept your guilty plea."}}], "real": "The Supreme Court (6-3) held that the trial judge committed no constitutional error in accepting Alford's guilty plea, because the State showed a strong factual basis and Alford clearly wanted to plead despite claiming innocence. It vacated the Fourth Circuit's judgment, which had ordered habeas relief, and sent the case back.", "cast": "fed", "added": "2026-10-13", "new": true}, {"id": "mccarthy", "name": "McCarthy v. United States", "cite": "394 U.S. 459 (1969)", "court": "U.S. Supreme Court", "url": "https://www.courtlistener.com/opinion/107892/mccarthy-v-united-states/", "verify": false, "charge": "Willfully attempting to evade income tax, 26 U.S.C. \u00a7 7201 (federal court, N.D. Illinois)", "setup": "McCarthy was indicted in federal court in Chicago on three counts of \"wilfully and knowingly\" trying to evade income taxes. He pleaded guilty to one count, and the government agreed to move to dismiss the other two. The judge asked about promises, threats and the maximum sentence, but never asked McCarthy himself whether he understood what the charge meant. At sentencing McCarthy said his failure to pay was \"not deliberate\" and blamed poor health. You're McCarthy, standing at the plea hearing.", "role": "You are the defendant entering a guilty plea in federal court.", "cards": [{"id": "mccarthy1", "case": "fed", "stage": "Rule 11 plea colloquy", "who": "judge", "say": "Has anybody threatened you that if you didn't enter a plea of guilty something would happen to you?", "say_real": true, "say_src": "McCarthy v. United States, 394 U.S. 459, App. A (1969) (district judge, quoted plea colloquy)", "need": [{"k": "a clear \"no threats\"", "any": ["no(body| one)? (has )?threatened", "no threats"]}, {"k": "your own free will", "any": ["own (free )?(will|volition)", "voluntar(y|ily)"]}], "avoid": [{"any": ["beg your pardon", "\\bhuh\\b", "\\bwhat\\?", "that'?s right"], "why": "A confused or yes-sounding answer to a \"no\" question leaves the record unclear about whether you were threatened."}], "win": "VOLUNTARY ON THE RECORD", "lose": "RECORD UNCLEAR", "model": "No, Your Honor. Nobody has threatened me. I'm pleading guilty voluntarily, of my own free will.", "why": "In the real colloquy McCarthy first answered \"I beg your pardon?\" and then \"That's right, of my own volition.\" That's a yes-sounding answer to a question about threats. A clean no, then the word voluntary, leaves nothing to argue about later.", "cite": "McCarthy v. United States, 394 U.S. 459 (1969)", "choices": [{"text": "No, Your Honor. Nobody has threatened me. I'm pleading voluntarily, of my own free will.", "ok": 1, "src": "model answer", "why": "Wins: a clear \"no threats\" and your own free will."}, {"text": "I beg your pardon?", "ok": 0, "src": "real record", "why": "A confused or yes-sounding answer to a \"no\" question leaves the record unclear about whether you were threatened."}, {"text": "That's right, of my own volition.", "ok": 0, "src": "real record", "why": "\"That's right\" sounds like yes to a question about threats. Say no first, then say it's voluntary."}, {"text": "Well, the prosecutor said it would go worse for me at trial.", "ok": 0, "src": "common mistake", "why": "That doesn't answer the question, and it suggests pressure. The judge would have to dig into it."}], "trap": {"2": "\"That's right\" sounds like yes to a question about threats. Say no first, then say it's voluntary."}}, {"id": "mccarthy2", "case": "fed", "stage": "Rule 11 plea colloquy (what the judge skipped)", "who": "quiz", "say": "The charge says McCarthy acted \"wilfully and knowingly,\" but his side later said the failure to pay was \"not deliberate.\" What did Rule 11 require the judge to do before accepting the plea?", "say_real": false, "need": [{"k": "address the defendant personally", "any": ["personally"]}, {"k": "his understanding of the nature of the charge", "any": ["nature of the charge", "understand(s|ing)? (of )?(the )?charge"]}, {"k": "a factual basis for the plea", "any": ["factual basis"]}], "avoid": [{"any": ["lawyer'?s (word|say-so)", "just (ask|trust) the lawyer", "only the maximum"], "why": "Rule 11 requires the judge to hear it from the defendant, not the lawyer, and to check more than the possible sentence."}], "win": "YOU KNOW RULE 11", "lose": "WRONG RULE", "model": "Under Rule 11 the judge had to address McCarthy personally, make sure he understood the nature of the charge, including that it requires willfulness, and find a factual basis for the plea.", "why": "The Supreme Court found that the judge never asked McCarthy himself whether he understood the charge. With a defendant who said his conduct wasn't deliberate, a factual basis for willfulness also wasn't clear.", "cite": "McCarthy v. United States, 394 U.S. 459 (1969); Fed. R. Crim. P. 11", "choices": [{"text": "Address him personally, make sure he understood the nature of the charge (including willfulness), and find a factual basis.", "ok": 1, "src": "model answer", "why": "Wins: address the defendant personally, his understanding of the nature of the charge, and a factual basis for the plea."}, {"text": "Nothing more. His lawyer's word that he wanted to plead was enough.", "ok": 0, "src": "common mistake", "why": "Rule 11 requires the judge to hear it from the defendant, not the lawyer, and to check more than the possible sentence."}, {"text": "Make sure he knew the maximum prison term and fine.", "ok": 0, "src": "common mistake", "why": "The judge did that. Knowing the maximum sentence doesn't show that he understood what the charge actually requires."}], "trap": {"2": "The judge did that. Knowing the maximum sentence doesn't show that he understood what the charge actually requires."}}, {"id": "mccarthy3", "case": "fed", "stage": "Before sentencing", "who": "judge", "say": "Mr. McCarthy, you've just said your failure to pay wasn't deliberate. Do you still want to stand on your plea of guilty?", "say_real": false, "need": [{"k": "ask to withdraw the plea", "any": ["withdraw"]}, {"k": "explain willfulness is the problem", "any": ["will?ful(ly|ness)?", "deliberate"]}, {"k": "talk to your lawyer first", "any": ["lawyer", "attorney", "counsel"]}], "avoid": [{"any": ["get (it|this) over", "\\bwhatever\\b", "just go ahead"], "why": "Shrugging it off locks in a plea to an element you just said you didn't commit."}], "win": "PLEA QUESTION RAISED", "lose": "PLEA LOCKED IN", "model": "Your Honor, I'd like a moment to speak with my lawyer, and I ask to withdraw my guilty plea. I didn't understand that the charge requires that I acted willfully, and I don't believe I did.", "why": "Willfulness is an element of tax evasion. If you didn't understand that and deny it, you should say so and ask to withdraw before sentencing, through your lawyer. The Supreme Court later let McCarthy plead anew because the judge never cleared this up.", "cite": "McCarthy v. United States, 394 U.S. 459 (1969)", "choices": [{"text": "I'd like to talk with my lawyer and ask to withdraw my plea. I didn't understand the charge requires acting willfully.", "ok": 1, "src": "model answer", "why": "Wins: ask to withdraw the plea, explain willfulness is the problem, and talk to your lawyer first."}, {"text": "Yes. I just want to get this over with.", "ok": 0, "src": "common mistake", "why": "Shrugging it off locks in a plea to an element you just said you didn't commit."}, {"text": "I want to withdraw my plea.", "ok": 0, "src": "common mistake", "why": "Good start, but give the reason (willfulness) and let your lawyer make the motion so it's done right."}], "trap": {"1": "Shrugging it off locks in a plea to an element you just said you didn't commit."}}], "real": "The Supreme Court reversed without dissent. Because the district judge accepted the plea without personally asking McCarthy whether he understood the nature of the charge, Rule 11 wasn't followed, and McCarthy was entitled to plead anew. The Court rested this on Rule 11 and did not reach the constitutional claims.", "cast": "state", "added": "2026-10-13", "new": true}];
